import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import MarginWrapper from '@/components/margin-wrapper'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { getAsesmenKeperawatanIGDAnak } from '@/services/asesmen-keperawatan'
// import { useGlobalStore } from '@/store/global.store'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

import AsuhanKeperawatan from './asuhan-keperawatan'
import ResikoJatuhTableIgdAnak from './resiko-jatuh-table-igd-anak'
import TableNyeri from './table-nyeri'

type AsesmenAwalKeperawatanIGDAnakProps = {
  noreg: string
  isReport?: boolean
}

const AsesmenAwalKeperawatanIGDAnak = ({
  noreg,
  isReport,
}: AsesmenAwalKeperawatanIGDAnakProps) => {
  // store
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.rekamMedis.asesmenAwalKeperawatanIgdAnak,
      noreg,
    ],
    queryFn: () =>
      getAsesmenKeperawatanIGDAnak({
        noreg: noreg!,
        noRm: pasien!.no_rm,
      }),
    enabled: !!noreg && !!pasien!.no_rm,
  })

  const res = data != null ? data.response : null

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.pengkajian.keluhan_utama == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 2a.3' rev='00.2025'>
      <div className='p-1 text-xs'>
        <HeaderFormulir
          nama={pasien!.nama_pasien}
          tanggalLahir={pasien!.tgl_lahir}
          noRm={pasien!.no_rm}
          nik={pasien!.nik}
        >
          <h3>PENGKAJIAN AWAL KEPERAWATAN</h3>
          <h3>GAWAT DARURAT</h3>
        </HeaderFormulir>
        {/* Cara Masuk */}
        <div className='border border-black my-1 p-2'>
          <Text
            kStyle='min-w-[250px]'
            k='Cara Masuk'
            v={res.pengkajian.cara_masuk ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Asal Pasien'
            v={res.pengkajian.asal_masuk ?? '-'}
          />
        </div>
        {/* Cara Masuk */}

        {/* Keluhan */}
        <div className='border border-black my-1 p-2'>
          <p className='flex-1 font-semibold'>Keluhan</p>
          <Text
            kStyle='min-w-[250px]'
            k='Keluhan Utama'
            v={res.pengkajian.keluhan_utama ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Sekarang'
            v={res.pengkajian.riwayat_penyakit_sekarang ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Dahulu'
            v={res.pengkajian.riwayat_penyakit_dahulu ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Penyakit Keluarga'
            v={res.pengkajian.riwayat_penhyakit_keluarga ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Pengobatan Dirumah'
            v={res.pengkajian.riwayat_pengobatan_dirumah ?? '-'}
          />
          <Text
            kStyle='min-w-[250px]'
            k='Riwayat Alergi'
            v={res.pengkajian.riwayat_alergi ?? '-'}
          />
        </div>
        {/* Keluhan */}

        {/* Pengkajian */}
        <div>
          <div className='flex'>
            <div className='flex-1 border border-black border-r-0 border-b-0  p-1'>
              <p className='flex-1 font-semibold text-center'>Pengkajian</p>
            </div>
            <div className='flex-[0.5] border border-black  border-b-0 p-1'>
              <p className='flex-1 font-semibold text-center'>
                Masalah Keperawatan
              </p>
            </div>
          </div>
          <div className='flex'>
            <div className='flex-1 border border-black border-r-0 p-1'>
              {/* FISIK */}
              <div className='mb-2'>
                <p className='flex-1 font-semibold'>PEMERIKSAAN FISIK</p>
                <Text
                  kStyle='min-w-[150px]'
                  k='Kepala'
                  v={res.fisik.kepala ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Leher dan Bahu'
                  v={res.fisik.leher ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Telinga'
                  v={res.fisik.telinga ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Hidung'
                  v={res.fisik.hidung ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Mulut'
                  v={res.fisik.mulut ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Gigi'
                  v={res.fisik.gigi ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Dada'
                  v={res.fisik.dada ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Abdomen'
                  v={res.fisik.abdomen ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Anggota Gerak'
                  v={res.fisik.anggota_gerak ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Genetalia'
                  v={res.fisik.genetalia ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Anus'
                  v={res.fisik.anus ?? '-'}
                />
              </div>
              {/* FISIK */}

              {/* PERSISTEM */}
              {/* <div className='mb-2'>
                <p className='flex-1 font-semibold'>
                  DATA PSIKOSOSIAL & SPIRITUAL
                </p>
                <Text
                  kStyle='min-w-[150px]'
                  k='Kebiasaan Merokok'
                  v={res.persistem.sistem_merokok ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Minum Alkohol'
                  v={res.persistem.sistem_minum_alkohol ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Status Psikologis'
                  v={res.persistem.sistem_spikologis ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Riwayat Pernah mengalami gangguan jiwa di masa lalu'
                  v={res.persistem.sistem_gangguan_jiwa ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Riwayat keinginan dan Percobaan Bunuh Diri'
                  v={res.persistem.sistem_bunuh_diri ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Riwayat Trauma Psikis'
                  v={res.persistem.sistem_trauma_psikis ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Hambatan Sosial'
                  v={res.persistem.sistem_hambatan_sosial ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Kebutuhan Spriritual'
                  v={res.persistem.sistem_hambatan_sosial ?? '-'}
                />
              </div>
              <div className='mb-2'>
                <p className='flex-1 font-semibold'>EKONOMI</p>
                <Text
                  kStyle='min-w-[150px]'
                  k='Ekonomi'
                  v={res.persistem.sistem_hambatan_ekonomi ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Penghasilan'
                  v={res.persistem.sistem_penghasilan ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Kultural'
                  v={res.persistem.sistem_kultural ?? '-'}
                />
              </div>
              <div className='mb-2'>
                <p className='flex-1 font-semibold'>FUNGSIONAL</p>
                <Text
                  kStyle='min-w-[150px]'
                  k='Menggunakan Alat Bantu'
                  v={res.persistem.sistem_alat_bantu ?? '-'}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Kebutuhan Khusus'
                  v={res.persistem.sistem_kebutuhan_khusus ?? '-'}
                />
              </div> */}
              {/* PERSISTEM */}
            </div>
            <div className='flex-[0.5] border border-black p-1'>
              <AsuhanKeperawatan data={res.asuhan_keperawatan} />
            </div>
          </div>
        </div>
        {/* Pengkajian */}

        <MarginWrapper>
          {/* Nyeri */}
          <TableNyeri data={res.nyeri} />
          {/* Nyeri */}
        </MarginWrapper>

        <MarginWrapper>
          {/* Resiko Jatuh */}
          <ResikoJatuhTableIgdAnak data={res.resiko_jatuh} />
          {/* Resiko Jatuh */}
        </MarginWrapper>

        <MarginWrapper>
          {/* Nutrisi */}
          <div className='border border-black my-1 p-2'>
            <p className='flex-1 font-semibold'>Pengkajian Nutrisi</p>
            {/* Table Head */}
            <div className=' flex'>
              <SimpleColumn head name='NO' className='w-[50px]' />
              <SimpleColumn head name='PARAMETER' />
              <SimpleColumn head name='HASIL' isLast />
            </div>
            {/* Table Head */}
            {/* Table Body */}
            <div className='flex'>
              <SimpleColumn className='text-xs border-t-0 w-[50px]' name='1.' />
              <SimpleColumn
                className='flex-1 text-xs border-t-0 text-start'
                name='Apakah pasien tampak kurus?'
              />
              <SimpleColumn
                className='flex-1 text-xs border-t-0'
                name={res.nutrisi.n1}
                isLast
              />
            </div>
            <div className='flex'>
              <SimpleColumn className='text-xs border-t-0 w-[50px]' name='2.' />
              <SimpleColumn
                className='flex-1 text-xs border-t-0 text-start'
                name='Apakah terdapat penurunan berat badan selama satu bulan terakhir ? (berdasarkan penilaian objektif data berat badan bila ada atau penilaian objektif data berat badan bila ada atau penilian subjktif orang tua pasien atau untuk baui < 1 tahub berat badan tidak anik selama 3 bulan terakhir'
              />
              <SimpleColumn
                className='flex-1 text-xs border-t-0'
                name={res.nutrisi.n2}
              />
            </div>
            <div className='flex'>
              <SimpleColumn className='text-xs border-t-0 w-[50px]' name='3.' />
              <SimpleColumn
                className='flex-1 text-xs border-t-0 text-start'
                name='Apakah terdapat salah satu dari kondisi tersebut? (diare >= 5 kali/hari dan muntah >= 3 kali/hari dalam seminggu terakhir atau asupan makanan berkurang selama 1 minggu terakhir'
              />
              <SimpleColumn
                className='flex-1 text-xs border-t-0'
                name={res.nutrisi.n3}
              />
            </div>
            <div className='flex'>
              <SimpleColumn className='text-xs border-t-0 w-[50px]' name='4.' />
              <SimpleColumn
                className='flex-1 text-xs border-t-0 text-start'
                name='Apakah terdapat penyakit atau keadaan yang mengakibatkan pasien berisiko mengalami malnutrisi'
              />
              <SimpleColumn
                className='flex-1 text-xs border-t-0'
                name={res.nutrisi.n4}
                isLast
              />
            </div>
            {/* Table Body */}

            <Text
              kStyle='min-w-[150px] my-1'
              k='Skor'
              v={`${res.nutrisi.nilai}`}
            />
            <SimpleColumn
              name='Bila skor >= 2 konsultasi ke ahli gizi'
              className='bg-yellow-400'
              isLast
            />
          </div>
          {/* Nutrisi */}
        </MarginWrapper>

        <p className='flex-1 font-semibold'>
          PENDIDIKAN KESEHATAN SAAT PASIEN PULANG
        </p>

        <p className='text-xs'>
          DISCHARGE PLANNING : {res.pengkajian.discharge_planning}
        </p>

        <MarginWrapper>
          {/* Observasi Pasien */}
          <div>
            <p className='flex-1 font-semibold mt-4 mb-2'>
              OBSERVASI PASIEN SAAT MENINGGALKAN IGD
            </p>

            <div className='flex items-center gap-[200px]'>
              <div>
                <Text
                  kStyle='min-w-[150px]'
                  k='TD'
                  v={`${res.observasi.td} mmHg`}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Nadi'
                  v={`${res.observasi.nadi} /menit`}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Pernapasan'
                  v={`${res.observasi.pernapasan} /menit`}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Suhu'
                  v={`${res.observasi.suhu} °C`}
                />
              </div>
              <div>
                <Text
                  kStyle='min-w-[150px]'
                  k='Kesadaran'
                  v={res.observasi.kesadaran}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='GCS'
                  v={`E : ${res.observasi.gcs_e}  V : ${res.observasi.gcs_v}  M : ${res.observasi.gcs_m}`}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Tinggi Badan'
                  v={`${res.vital_sign.tinggi_badan} cm`}
                />
                <Text
                  kStyle='min-w-[150px]'
                  k='Berat Badan'
                  v={`${res.vital_sign.berat_badan} kg`}
                />
              </div>
            </div>
          </div>
          {/* Observasi Pasien */}
        </MarginWrapper>

        <MarginWrapper>
          {/* Perawat */}
          <div className='mt-[50px] p-2 mb-1 m-2 flex items-center justify-between'>
            <div className='flex flex-col items-center justify-center gap-4 text-center'>
              {res != null && res.perawat.nama != '' ? (
                <>
                  <div>
                    <p className='text-xs font-semibold'>
                      Baturaja, {formatDateTime(res.pengkajian.insert_dttm)}
                      <br />
                    </p>
                  </div>
                  <QRCode
                    value={res.perawat.nama}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs font-semibold'>
                    (
                    <span className='hide-when-print'>{res.perawat.id} - </span>
                    {res.perawat.nama})
                  </p>
                </>
              ) : (
                <div className='h-[100px]' />
              )}
            </div>
            <div className='flex flex-col items-center justify-center gap-4 text-center'>
              {pasien != null && pasien.nama_pasien != '' ? (
                <>
                  <div>
                    <p className='text-xs font-semibold'>Keluarga / Pasien</p>
                  </div>
                  <QRCode
                    value={pasien.nama_pasien}
                    className='h-[50px] w-[50px]'
                  />
                  <p className='text-xs font-semibold'>
                    ( {pasien.nama_pasien} )
                  </p>
                </>
              ) : (
                <div className='h-[100px]' />
              )}
            </div>
          </div>
        </MarginWrapper>
        {/* Perawat */}
      </div>
    </LayoutBorderNo>
  )
}

export default AsesmenAwalKeperawatanIGDAnak
