import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { Intervensi } from '@/models/resiko-jatuh'
import { getIntervensiResikoJatuh } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

interface ReportIntervensiResikoJatuhProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

const INTERVENSI_RENDAH_SEDANG = [
  'Lakukan orientasi kamar kepada pasien dan keluarga dan edukasi cara mencegah jatuh',
  'Pastikan roda tempat tidur pasien dalam keadaan terkunci dan kunci tidak rusak',
  'Dekatkan bel panggil dan pastikan bel berfungsidengan baik',
  'Dekatkan benda-benda pribadi dapat terjangkau pasien',
  'Pastikan pencahayaan ruangan adekuat, jalur pasien berjalan tidak licin, dan bebas penghalang',
  'Pagar tempat tidur terpasang dengan baik',
  'Posisikan tempat tidur serendah mungkin',
  'Terapkan seluruh intervensi resiko jatuh rendah',
  'Pantau obat yang dapat meningkatkan resiko jatuh',
  'Konsultasikan dengan Dokter mengenai kebutuhan pasien dengan gangguan keseimbangan',
  'Pantau adanya hipotensi, jika pasien mengeluh pusing atau vertigo, dan ajarkan pasien bangun dari tempat tidur',
]

const INTERVENSI_TINGGI = [
  'Terapkan seluruh intervensi resiko jatuh rendah dan sedang',
  'Komunikasikan resiko jatuh pasien saat pergantian shift dan pastikan penanda resiko jatuh terpasang',
  'Awasi dan bantu pasien saat eliminasi, perpindahan, dan saat aktifitas berjalan pasien',
  'Pastikan setiap saat pasien ditunggui oleh keluarga atau penunggu pasien',
  'Observasi dan lakukan kunjungan keruangan pasien tiap tiga jam sekali',
  'Tempatkan pasien pada kamar yang paling dekat dengan Nurs station / Pos Perawatan',
]

export function ReportIntervensiResikoJatuh({
  isReport = false,
  noreg = '',
}: ReportIntervensiResikoJatuhProps) {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.intervensiResikoJatuh, noreg],
    queryFn: () =>
      getIntervensiResikoJatuh({
        noReg: noreg,
        kdBagian: pasien?.kd_bagian || '',
      }),
  })

  const result = data?.response != null ? data?.response.resiko_jatuh : []

  // group by date
  const groupedByDate: Record<string, Intervensi[]> = result.reduce(
    (acc, item) => {
      const date = formatDate(item.insert_dttm)
      if (!acc[date]) {
        acc[date] = []
      }
      acc[date].push(item)
      return acc
    },
    {} as Record<string, Intervensi[]>,
  )

  const dates = Object.keys(groupedByDate).sort()
  const shifts = ['Pagi', 'Siang', 'Malam']

  // Helper function to get checkmark for specific intervensi, date, and shift
  const getCheckmark = (
    dateStr: string,
    shiftName: string,
    resikoIndex: number,
  ): string => {
    const interventions = groupedByDate[dateStr] || []
    const shiftData = interventions.find((item) => item.shift === shiftName)
    if (!shiftData) return ''
    const key = `resiko${resikoIndex + 1}` as keyof Intervensi
    return shiftData[key] ? '✓' : ''
  }

  // Helper function to get nama perawat for specific date and shift
  const getNamaPerawat = (dateStr: string, shiftName: string): string => {
    const interventions = groupedByDate[dateStr] || []
    const shiftData = interventions.find((item) => item.shift === shiftName)
    if (!shiftData) return ''
    return shiftData.nama_perawat || ''
  }

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <div className='landscape:max-w-full landscape:m-0'>
      <style>{`
        @media print {
          @page {
            size: A4 landscape;
            margin: 10mm;
          }
          body {
            margin: 0;
            padding: 0;
          }
        }
      `}</style>
      <LayoutBorderNo no='RM 8d' rev='01.2020' isReport={isReport}>
        {/* Content */}
        <div className='p-2'>
          <HeaderFormulir
            nama={pasien!.nama_pasien}
            tanggalLahir={pasien!.tgl_lahir}
            noRm={pasien!.no_rm}
            nik={pasien!.nik}
          >
            <h3>
              FORMULIR INTERVENSI <br />
              PENCEGAHAN PASIEN JATUH
            </h3>
          </HeaderFormulir>

          {/* SECTION 1: INTERVENSI RISIKO RENDAH DAN SEDANG */}
          <div className='mb-4'>
            <div className='text-xs font-semibold mb-2'>
              Intervensi risiko rendah dan sedang
            </div>

            {/* Header Row - Dates */}
            <div className='flex text-xs'>
              <SimpleColumn head name='No' className='w-[40px]' />
              <SimpleColumn
                head
                name='Intervensi risiko rendah dan sedang'
                className='flex-1'
              />
              {dates.map((date) => (
                <div key={date} className='flex'>
                  <SimpleColumn head name={date} className='w-[45px]' />
                  <SimpleColumn head name='' className='w-[45px]' />
                  <SimpleColumn
                    head
                    name=''
                    className='w-[45px]'
                    isLast={date === dates[dates.length - 1]}
                  />
                </div>
              ))}
            </div>

            {/* PKL Sub-header Row - Shifts */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn name='' className='flex-1 border-t-0 text-center' />
              {dates.map((date) => (
                <div key={`shifts-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`${date}-${shift}`}
                      name={shift}
                      className='w-[45px] border-t-0 text-center text-[10px]'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>

            {/* Intervention Rows */}
            {INTERVENSI_RENDAH_SEDANG.map((intervensi, idx) => (
              <div key={idx} className='flex text-xs'>
                <SimpleColumn
                  name={`${idx + 1}.`}
                  className='w-[40px] border-t-0'
                />
                <SimpleColumn
                  name={intervensi}
                  className='flex-1 border-t-0 items-start'
                />
                {dates.map((date) => (
                  <div key={`${date}-${idx}`} className='flex'>
                    {shifts.map((shift) => (
                      <SimpleColumn
                        key={`${date}-${shift}-${idx}`}
                        name={getCheckmark(date, shift, idx)}
                        className='w-[45px] border-t-0 text-center font-bold'
                        isLast={
                          date === dates[dates.length - 1] &&
                          shift === shifts[shifts.length - 1]
                        }
                      />
                    ))}
                  </div>
                ))}
              </div>
            ))}

            {/* Nama Perawat Row */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn
                name='Nama perawat yang melakukan intervensi'
                className='flex-1 border-t-0 font-semibold'
              />
              {dates.map((date) => (
                <div key={`perawat-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`perawat-${date}-${shift}`}
                      name={getNamaPerawat(date, shift)}
                      className='w-[45px] border-t-0 text-center text-xs break-words overflow-hidden line-clamp-2'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>

          {/* SECTION 2: INTERVENSI RISIKO TINGGI */}
          <div>
            <div className='text-xs font-semibold mb-2 mt-[120px]'>
              Intervensi risiko tinggi
            </div>

            {/* Header Row - Dates */}
            <div className='flex text-xs'>
              <SimpleColumn head name='No' className='w-[40px]' />
              <SimpleColumn
                head
                name='Intervensi risiko tinggi'
                className='flex-1'
              />
              {dates.map((date) => (
                <div key={`high-${date}`} className='flex'>
                  <SimpleColumn head name={date} className='w-[45px]' />
                  <SimpleColumn head name='' className='w-[45px]' />
                  <SimpleColumn
                    head
                    name=''
                    className='w-[45px]'
                    isLast={date === dates[dates.length - 1]}
                  />
                </div>
              ))}
            </div>

            {/* PKL Sub-header Row - Shifts */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn name='' className='flex-1 border-t-0 text-center' />
              {dates.map((date) => (
                <div key={`shifts-high-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`${date}-${shift}-high`}
                      name={shift}
                      className='w-[45px] border-t-0 text-center text-[10px]'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>

            {/* Intervention Rows */}
            {INTERVENSI_TINGGI.map((intervensi, idx) => (
              <div key={`high-${idx}`} className='flex text-xs'>
                <SimpleColumn
                  name={`${idx + 1}.`}
                  className='w-[40px] border-t-0'
                />
                <SimpleColumn
                  name={intervensi}
                  className='flex-1 border-t-0 items-start'
                />
                {dates.map((date) => (
                  <div key={`${date}-high-${idx}`} className='flex'>
                    {shifts.map((shift) => (
                      <SimpleColumn
                        key={`${date}-${shift}-high-${idx}`}
                        name={getCheckmark(date, shift, idx + 11)}
                        className='w-[45px] border-t-0 text-center font-bold'
                        isLast={
                          date === dates[dates.length - 1] &&
                          shift === shifts[shifts.length - 1]
                        }
                      />
                    ))}
                  </div>
                ))}
              </div>
            ))}

            {/* Nama Perawat Row */}
            <div className='flex text-xs'>
              <SimpleColumn name='' className='w-[40px] border-t-0' />
              <SimpleColumn
                name='Nama perawat yang melakukan intervensi'
                className='flex-1 border-t-0 font-semibold'
              />
              {dates.map((date) => (
                <div key={`perawat-high-${date}`} className='flex'>
                  {shifts.map((shift) => (
                    <SimpleColumn
                      key={`perawat-high-${date}-${shift}`}
                      name={getNamaPerawat(date, shift)}
                      className='w-[45px] border-t-0 text-center text-xs break-words overflow-hidden line-clamp-2'
                      isLast={
                        date === dates[dates.length - 1] &&
                        shift === shifts[shifts.length - 1]
                      }
                    />
                  ))}
                </div>
              ))}
            </div>
          </div>
        </div>
        {/* Content */}
      </LayoutBorderNo>
    </div>
  )
}
