import { Eye, Trash } from 'lucide-react'

import { ColumnDef } from '@tanstack/react-table'

import { Button } from '@/components/ui/button'
import { ResponseTriaseNew } from '@/models/triase-new'
import { useGlobalStore } from '@/store/global.store'
import { formatDateTime } from '@/utils/formatDate'

export const columns: ColumnDef<ResponseTriaseNew>[] = [
  {
    header: 'No.',
    cell: ({ row }) => <p>{row.index + 1}</p>,
  },
  {
    accessorKey: 'tanggal',
    header: 'Tanggal',
    cell: ({ row }) => {
      const item = row.original
      return <p>{formatDateTime(item.insert_dttm) + ' WIB'}</p>
    },
  },
  {
    accessorKey: 'nama',
    header: 'Nama',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.nama_pasien}</p>
    },
  },
  {
    accessorKey: 'perawat',
    header: 'Perawat',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.nama_perawat}</p>
    },
  },
  {
    accessorKey: 'dokter',
    header: 'Dokter',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.nama_dokter}</p>
    },
  },
  {
    accessorKey: 'action',
    header: 'Action',
    cell: ({ row }) => {
      // eslint-disable-next-line react-hooks/rules-of-hooks
      const { setDialogId, setItem } = useGlobalStore()
      const item = row.original
      return (
        <div className='flex items-center gap-2'>
          <Button
            className='flex-1 text-blue-500 h-[30px]'
            variant='outline'
            onClick={() => {
              setDialogId('dialog-detail-triase-new')
              setItem(item)
            }}
          >
            <Eye />
          </Button>
          <Button
            className='flex-1 bg-red-500 hover:bg-gray-300 h-[30px]'
            onClick={() => {
              setDialogId('dialog-delete-triase-new')
              setItem(item)
            }}
          >
            <Trash />
          </Button>
        </div>
      )
    },
  },
]
