import { ReqLabModel } from '@/models/req-lab'
import type { Response } from '@/type'

import { post } from './api-2'

const getReportReqLab = async ({
  noreg,
  kdBagian,
  noRm,
  id,
}: {
  noreg: string
  kdBagian: string
  noRm: string
  id: string
}): Promise<Response<ReqLabModel>> => {
  const response = await post(`/v1/permintaan-pemeriksaan-lab/report`, {
    no_reg: noreg,
    kd_bagian: kdBagian,
    no_rm: noRm,
    id: id,
  })

  return response.data
}

const getAllReportReqLab = async ({
  noreg,
  kdBagian,
  noRm,
  id,
}: {
  noreg: string
  kdBagian: string
  noRm: string
  id: string
}): Promise<Response<ReqLabModel[]>> => {
  const response = await post(`/v1/permintaan-pemeriksaan-lab/all`, {
    no_reg: noreg,
    kd_bagian: kdBagian,
    no_rm: noRm,
    id: id,
  })

  return response.data
}

export { getReportReqLab, getAllReportReqLab }
