import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { getReportRujukanPasien } from '@/services/rujukan-pasien'
import { constants } from '@/utils/constants'
import { formatDate } from '@/utils/formatDate'

import { TextField } from './text-field'
import { TextTitle } from './text-title'

interface ReportSuratRujukanPasienProps {
  isReport?: boolean
  noreg?: string
  no?: string
  noRm?: string
  kdBagian?: string
}

const ReportSuratRujukanPasien = ({
  isReport,
  noreg,
  noRm,
}: ReportSuratRujukanPasienProps) => {
  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rujukanPasien, noreg],
    queryFn: () => getReportRujukanPasien({ noreg: noreg!, no_rm: noRm! }),
    enabled: !!noreg,
  })

  if (isLoading) return <Loading />
  if (isError) return <Error />

  const d = data != null ? data.response.data : null
  const pasien = data?.response.pasien

  if (d == null) return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 15' rev='02.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama ?? ''}
          tanggalLahir={formatDate(pasien!.tgl_lahir) ?? ''}
          noRm={noRm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center'>
            SURAT RUJUKAN PASIEN {d.tipe}
            <br />
            No Surat : {d.nomor_surat}
          </h3>
        </HeaderFormulir>

        <div className='grid grid-cols-2 gap-2'>
          <TextField title='Jenis Pembayaran' value={d.jenis_pembayaran} />
          <TextField title='Nomor Kartu' value={d.nomor_kartu} />
        </div>
        <div className='grid grid-cols-2 gap-2'>
          <TextField
            title='Rumah Sakit yang Dituju'
            value={d.rumah_sakit_tujuan}
          />
          <TextField title='Dokter Tujuan' value={d.dokter_tujuan} />
        </div>
        <p className='text-xs my-2'>
          Dengan hormat, <br />
          Mohon konsul/perawatan selanjutnya untuk pasien atas nama tersebut
        </p>
        <TextField title='Alasan Rujuk' value={d.alasan_rujuk} />
        <TextField title='Diagnosa' value={d.diagnosa} />
        <TextField title='Kondisi Pasien Saat rujuk' value={d.kondisi_pasien} />
        <TextField title='Kesadaran' value={d.kesadaran} />
        <div className=''>
          <TextField title='GCS E' value={d.gcs_e} />
          <TextField title='GCS M' value={d.gcs_m} />
          <TextField title='GCS V' value={d.gcs_v} />
          <TextField title='TD' value={d.td != '' ? `${d.td} mmHg` : ''} />
        </div>
        <div className=''>
          <TextField
            title='Nadi'
            value={d.nadi != '' ? `${d.nadi} x/menit` : ''}
          />
          <TextField title='Suhu' value={d.suhu != '' ? `${d.suhu} °C` : ''} />
          <TextField
            title='Pernafasan'
            value={d.pernafasan != '' ? `${d.pernafasan} x/menit` : ''}
          />
          <TextField title='SPO2' value={d.spo2 != '' ? `${d.spo2} %` : ''} />
        </div>
        <TextTitle title={`Skala Nyeri : ${d.skala_nyeri}`} />
        <TextTitle title='Pemeriksaan Penunjang yang telah dilakukan' />
        <p className='text-xs'>{d.pemeriksaan_penunjang}</p>
        <TextTitle title='Terapi / Pengobatan yang telah diberikan' />
        <p className='text-xs'>{d.terapi}</p>
        <TextTitle title='Kebutuhan pelayanan yang lebih lanjut' />
        <p className='text-xs'>{d.kebutuhan}</p>
        <TextTitle title='Prosedur intervensi yang dilakukan' />
        <p className='text-xs'>{d.prosedur}</p>

        <div className='flex justify-between items-start mt-10'>
          {d.tipe == 'RANAP' && (
            <div className='text-center'>
              <p className='text-xs font-semibold'>
                Petugas yang menerima rujukan
              </p>
              <div className='h-[60px]' />
              <p className='text-xs' />
            </div>
          )}
          <div className='text-center'>
            <p className='text-xs font-semibold'>
              Hormat kami, {formatDate(d.insert_dttm)}
              <br />
              Dokter Penanggung Jawab Pelayanan (DPJP)
            </p>
            <div className='flex justify-center mt-2'>
              {d.nama_dokter != '' ? (
                <QRCode value={d.nama_dokter} size={70} />
              ) : (
                <div className='h-[70px]' />
              )}
            </div>
            <p className='text-xs mt-2'>
              {d.nama_dokter || '( ................................. )'}
            </p>
          </div>
        </div>
      </div>
    </LayoutBorderNo>
  )
}

export default ReportSuratRujukanPasien
