import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import {
  getPemasanganFoleyCatheter,
  getPemasanganIvp,
  getPemasanganNgt,
} from '@/services/pemasangan-pemantauan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextTitle } from './text-title'

type ReportDataPemasanganProps = {
  noreg: string
  kdBagian: string
  isReport?: boolean
}

const ReportDataPemasangan = ({
  noreg,
  kdBagian,
  isReport,
}: ReportDataPemasanganProps) => {
  const { pasien } = usePasienStore((state) => state)

  const ivp = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemasanganIvp, noreg],
    queryFn: () => getPemasanganIvp(noreg, kdBagian),
    enabled: !!noreg,
  })

  const foley = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemasanganFoleyCatheter, noreg],
    queryFn: () => getPemasanganFoleyCatheter(noreg, kdBagian),
    enabled: !!noreg,
  })

  const ngt = useQuery({
    queryKey: [constants.queryKey.rekamMedis.pemasanganNgt, noreg],
    queryFn: () => getPemasanganNgt(noreg, kdBagian),
    enabled: !!noreg,
  })

  if (ivp.isLoading || foley.isLoading || ngt.isLoading) return <Loading />
  if (ivp.isError || foley.isError || ngt.isError) return <Error />

  const ivpData = ivp.data != null ? ivp.data.response : []
  const foleyData = foley.data != null ? foley.data.response : []
  const ngtData = ngt.data != null ? ngt.data.response : []

  if (
    (ivpData == null || ivpData.length == 0) &&
    (foleyData == null || foleyData.length == 0) &&
    (ngtData == null || ngtData.length == 0)
  )
    return null

  return (
    <LayoutBorderNo isReport={isReport} no='RM 10' rev='01.2020'>
      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-1'>
          DATA PEMASANGAN INFUS, DOWER CATHETER, NGT/OGT
        </h1>
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            ruangan={pasien.bagian}
            tanggalLahir={pasien.tgl_lahir}
          />
        )}

        {/* Pemasangan Infus (IVP) */}
        <TextTitle title='Pemasangan Infus' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Tanggal</th>
              <th className='border border-black px-1'>Jam</th>
              <th className='border border-black px-1'>Set Infus</th>
              <th className='border border-black px-1'>Lokasi Pemasangan</th>
              <th className='border border-black px-1'>Nomor Jarum</th>
              <th className='border border-black px-1'>Keterangan</th>
              <th className='border border-black px-1'>Perawat</th>
            </tr>
          </thead>
          <tbody>
            {ivpData.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>{item.tanggal}</td>
                <td className='border border-black px-1'>{item.jam}</td>
                <td className='border border-black px-1'>{item.set_infus}</td>
                <td className='border border-black px-1'>
                  {item.lokasi_pemasangan}
                </td>
                <td className='border border-black px-1'>{item.nomor_jarum}</td>
                <td className='border border-black px-1'>{item.keterangan}</td>
                <td className='border border-black px-1'>{item.perawat}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Pemasangan Dower Catheter */}
        <TextTitle title='Pemasangan Dower Catheter' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Tanggal</th>
              <th className='border border-black px-1'>Jam</th>
              <th className='border border-black px-1'>Jenis Urine</th>
              <th className='border border-black px-1'>Cabang</th>
              <th className='border border-black px-1'>Ukuran</th>
              <th className='border border-black px-1'>Balon Terisi</th>
              <th className='border border-black px-1'>Indikasi Pemasangan</th>
              <th className='border border-black px-1'>Keterangan</th>
              <th className='border border-black px-1'>Perawat</th>
            </tr>
          </thead>
          <tbody>
            {foleyData.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>{item.tanggal}</td>
                <td className='border border-black px-1'>{item.jam}</td>
                <td className='border border-black px-1'>{item.jenis_urine}</td>
                <td className='border border-black px-1'>{item.cabang}</td>
                <td className='border border-black px-1'>{item.ukuran}</td>
                <td className='border border-black px-1'>{item.balon_terisi}</td>
                <td className='border border-black px-1'>
                  {item.indikasi_pemasangan}
                </td>
                <td className='border border-black px-1'>{item.keterangan}</td>
                <td className='border border-black px-1'>{item.perawat}</td>
              </tr>
            ))}
          </tbody>
        </table>

        {/* Pemasangan NGT/OGT */}
        <TextTitle title='Pemasangan NGT/OGT' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Tanggal</th>
              <th className='border border-black px-1'>Jam</th>
              <th className='border border-black px-1'>Lokasi Pemasangan</th>
              <th className='border border-black px-1'>Ukuran</th>
              <th className='border border-black px-1'>Panjang</th>
              <th className='border border-black px-1'>Indikasi Pemasangan</th>
              <th className='border border-black px-1'>Keterangan</th>
              <th className='border border-black px-1'>Perawat</th>
            </tr>
          </thead>
          <tbody>
            {ngtData.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>{item.tanggal}</td>
                <td className='border border-black px-1'>{item.jam}</td>
                <td className='border border-black px-1'>
                  {item.lokasi_pemasangan}
                </td>
                <td className='border border-black px-1'>{item.ukuran}</td>
                <td className='border border-black px-1'>{item.panjang}</td>
                <td className='border border-black px-1'>
                  {item.indikasi_pemasangan}
                </td>
                <td className='border border-black px-1'>{item.keterangan}</td>
                <td className='border border-black px-1'>{item.perawat}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </LayoutBorderNo>
  )
}

export default ReportDataPemasangan
