import { ColumnDef } from '@tanstack/react-table'

import { Button } from '@/components/ui/button'
import { SkriningPasienLuar } from '@/models/skrining-pasien-luar'
import { useGlobalStore } from '@/store/global.store'
import { formatDateTime } from '@/utils/formatDate'

export const columns: ColumnDef<SkriningPasienLuar>[] = [
  {
    header: 'No.',
    cell: ({ row }) => <p>{row.index + 1}</p>,
  },
  {
    accessorKey: 'tanggal',
    header: 'Tanggal',
    cell: ({ row }) => {
      const item = row.original
      return <p>{formatDateTime(item.insert_dttm) + ' WIB'}</p>
    },
  },
  {
    accessorKey: 'nama',
    header: 'Nama Pasien',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.nama}</p>
    },
  },
  {
    accessorKey: 'diagnosa',
    header: 'Diagnosa',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.diagnosa}</p>
    },
  },
  {
    accessorKey: 'rujukan',
    header: 'Rujukan',
    cell: ({ row }) => {
      const item = row.original
      return <p>{item.data.rujukan}</p>
    },
  },
  {
    accessorKey: 'action',
    header: 'Action',
    cell: ({ row }) => {
      // eslint-disable-next-line react-hooks/rules-of-hooks
      const { setDialogId, setItem } = useGlobalStore()
      const item = row.original
      return (
        <div className='flex items-center gap-4'>
          <Button
            className='flex-1 text-blue-500 h-[30px]'
            variant='outline'
            onClick={() => {
              setDialogId('dialog-detail-skrining-pasien-luar')
              setItem(item)
            }}
          >
            LIHAT
          </Button>
          <Button
            className='flex-1 bg-red-500 hover:bg-gray-300 h-[30px]'
            onClick={() => {
              setDialogId('dialog-delete-skrining-pasien-luar')
              setItem(item)
            }}
          >
            HAPUS
          </Button>
        </div>
      )
    },
  },
]
