import { useState } from 'react'

import { createFileRoute } from '@tanstack/react-router'

import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { getResumeRanap } from '@/services/rekam-medis'
import { constants } from '@/utils/constants'

export const Route = createFileRoute('/resume')({
  component: Resume,
})

function Resume() {
  const [noreg, setNoreg] = useState<string>('')
  const [kdBagian, setKdBagian] = useState<string>('')
  const [hasResume, setHasResume] = useState(false)

  async function onCari(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault()

    if (noreg == '' || kdBagian == '') {
      alert('Nomor Registrasi dan Ruangan wajib diisi!')
      return
    }
    const res = await getResumeRanap(noreg, kdBagian, 'AKHIR')
    const data = res.response != null ? res.response : null

    if (data != null) {
      if (data.indikasi_ranap.keluhan_utama != '') {
        setHasResume(true)
      }
    }
  }

  return (
    <div className='min-h-screen max-width flex flex-col items-center justify-center'>
      <div className='p-4 h-[300px] w-[500px] border shadow-md rounded-md flex flex-col items-center justify-center'>
        <h1 className='text-2xl font-medium text-center mb-4'>
          Ringkasan Pulang Rawat Inap
        </h1>
        {/* Select No Reg */}
        <div className='w-full flex items-center mb-4'>
          <Select value={kdBagian}>
            <SelectTrigger className='w-full'>
              <SelectValue placeholder='Pilih Ruangan' />
            </SelectTrigger>
            <SelectContent>
              <SelectGroup>
                {ruangan.map((item, index) => (
                  <SelectItem
                    key={index}
                    value={item.kd_bagian}
                    onPointerDown={() => {
                      setKdBagian(item.kd_bagian)
                    }}
                  >
                    {item.nama}
                  </SelectItem>
                ))}
              </SelectGroup>
            </SelectContent>
          </Select>
        </div>
        {/* Select No Reg */}
        <form onSubmit={onCari} className='w-full'>
          <Input
            placeholder='Nomor Registrasi'
            className='mb-4 w-full'
            value={noreg}
            onChange={(e) => setNoreg(e.target.value)}
          />
          <Button className='w-full' type='submit'>
            CARI
          </Button>
        </form>
        {hasResume && (
          <a
            className='mt-4 underline'
            target='_blank'
            href={`http://192.168.0.5:8383/report/resume-rekam-medis?noreg="${noreg}"&no=RM.%20&kd_bagian=${kdBagian}`}
            onClick={() => setHasResume(false)}
          >
            Lihat Ringkasan Rawat Inap
          </a>
        )}
      </div>
      <p className='text-xs mt-4'>v{constants.version}</p>
    </div>
  )
}

const ruangan = [
  { nama: 'FRANSISKUS 1', kd_bagian: 'FRA1' },
  { nama: 'FRANSISKUS 2', kd_bagian: 'FRA2' },
  { nama: 'ELISABETH 1', kd_bagian: 'ELI1' },
  { nama: 'ELISABETH 2', kd_bagian: 'ELI2' },
  { nama: 'THERESIA', kd_bagian: 'THER' },
]
