import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import type { AsesmenPraBedah } from '@/models/asesmen-pra'
import { getAsesmenPraBedah } from '@/services/asesmen-pra-bedah'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportAsesmenPraBedahProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

const INIT_DATA: AsesmenPraBedah = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  insert_user_id: '',
  pelayanan: '',
  diagnosa: '',
  riwayat_penyakit_dahulu: '',
  persiapan_transfusi: '',
  rencana_jadwal_operasi: '',
  rencana_tindakan_operasi: '',
  rencana_perawat_pasca_operasi: '',
  instruksi_pasca_operasi: '',
  instruksi_pra_bedah: '',
  user: '',
}

const ReportAsesmenPraBedah = ({
  isReport,
  noreg,
  kdBagian,
}: ReportAsesmenPraBedahProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenPraBedah, noreg],
    queryFn: () => getAsesmenPraBedah(noreg!, kdBagian!),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : INIT_DATA

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.noreg === '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 17' rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3'>
            PENGKAJIAN PRA BEDAH
          </h3>
        </HeaderFormulir>

        <div className='flex p-2'>
          <p className='text-xs text-black'>
            Tanggal Pengkajian : {formatDateTime(res.insert_dttm)} WIB
          </p>
        </div>

        <div className='gap-4 border border-black p-1 mb-1'>
          <div className='mb-4'>
            <TextField
              valueClass='mb-1'
              title='Diagnosa'
              value={res.diagnosa}
            />
            <TextField
              valueClass='mb-1'
              title='Riwayat Penyakit Dahulu'
              value={res.riwayat_penyakit_dahulu}
            />
            <TextField
              valueClass='mb-1'
              title='Persiapan Transfusi'
              value={res.persiapan_transfusi}
            />
            <TextField
              valueClass='mb-1'
              title='Rencana Jadwal Operasi'
              value={res.rencana_jadwal_operasi}
            />
            <TextField
              valueClass='mb-1'
              title='Rencana Tindakan Operasi'
              value={res.rencana_tindakan_operasi}
            />
            <TextField
              valueClass='mb-1'
              title='Rencana Perawatan Pasca Operasi'
              value={res.rencana_perawat_pasca_operasi}
            />
            <TextField
              valueClass='mb-1'
              title='Instruksi Pasca Operasi'
              value={res.instruksi_pasca_operasi}
            />
            <TextField
              valueClass='mb-1'
              title='Instruksi Pra Bedah'
              value={res.instruksi_pra_bedah}
            />
          </div>
        </div>
        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <div className='flex items-end justify-between'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>
                Baturaja, {formatDate(res.insert_dttm)}
              </p>
              {res.user ? (
                <>
                  <QRCode value={res.user} className='h-[50px] w-[50px]' />
                  <p>( {res.user} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportAsesmenPraBedah
