import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { ImplementasiMppModel } from '@/models/implementasi-mpp'
import { getImplementasiMpp } from '@/services/implementasi-mpp'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

interface ReportImplementasiMppProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  noRm?: string
}

const init: ImplementasiMppModel = {
  data: [],
  pasien: {
    id: '',
    nik: '',
    nama: '',
    agama: '',
    jeniskelamin: '',
    email: '',
    hp: '',
    tgl_lahir: '',
    alamat: '',
  },
}

const ReportImplementasiMpp = ({
  isReport,
  noreg,
  kdBagian,
  noRm,
}: ReportImplementasiMppProps) => {
  // const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.implementasiMpp, noreg],
    queryFn: () =>
      getImplementasiMpp({
        no_reg: noreg!,
        kd_bagian: kdBagian!,
        no_rm: noRm!,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.data.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 21a' rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={res.pasien.nama}
          tanggalLahir={formatDate(res.pasien.tgl_lahir)}
          noRm={res.pasien.id}
          nik={res.pasien.nik}
        >
          <h3 className='text-xs font-bold text-center py-3 whitespace-pre-wrap'>
            CATATAN IMPLEMENTASI MPP
            <br />
            FORM B
          </h3>
        </HeaderFormulir>
      </div>

      <div className='p-4'>
        {/* header */}
        <div className='text-xs flex'>
          <SimpleColumn className='flex-1' head name='Tanggal & Jam' />
          <SimpleColumn className='flex-1' head name='Pelaksanaan' />
          <SimpleColumn className='flex-1' head name='Monitor' />
          <SimpleColumn
            className='flex-1'
            head
            name='Fasilitas, koordinasi, kolaborasi, dan komunikasi'
          />
          <SimpleColumn className='flex-1' head name='Advokasi' />
          <SimpleColumn className='flex-1' head name='Hasil pelayanan' />
          <SimpleColumn className='flex-1' head name='Terminasi' />
          <SimpleColumn className='flex-1' head name='Petugas' isLast />
        </div>
        {/* header */}
        {/* body */}
        {res.data.map((item, i) => (
          <div className='text-xs flex flex-1' key={i}>
            <SimpleColumn
              className='border-t-0 flex-1'
              name={formatDateTime(item.insert_dttm) + ' WIB'}
            />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.pelaksanaan}
            />
            <SimpleColumn className='border-t-0 flex-1' name={item.monitor} />
            <SimpleColumn className='border-t-0 flex-1' name={item.fasilitas} />
            <SimpleColumn className='border-t-0 flex-1' name={item.advokasi} />
            <SimpleColumn className='border-t-0 flex-1' name={item.hasil} />
            <SimpleColumn className='border-t-0 flex-1' name={item.terminasi} />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.petugas}
              hasQR
              isLast
            />
          </div>
        ))}
        {/* body */}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportImplementasiMpp
