import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getMonitoringCairan, getTransfusiDarah } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

type MonitoringCairanProps = {
  noreg: string
  isReport?: boolean
}

const MonitoringCairan = ({ noreg, isReport }: MonitoringCairanProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.monitoringCairan, noreg],
    queryFn: () => getMonitoringCairan(noreg),
    enabled: !!noreg,
  })

  const resTransfusi = useQuery({
    queryKey: [constants.queryKey.rekamMedis.transfusiDarah, noreg],
    queryFn: () => getTransfusiDarah(noreg),
    enabled: !!noreg,
  })
  console.log('resTransfusi', resTransfusi)

  const res = data != null ? data.response : null
  const result = resTransfusi.data != null ? resTransfusi.data.response : null
  console.log('res monitoring cairan', res)
  console.log('res transfusi darah', result)

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null) return null

  return (
    <LayoutBorderNo isReport={isReport} no='RM 12'>
      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-1'>
          Pemasukan dan Pengeluaran Cairan
        </h1>

        {/* Informasi Pasien */}
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            ruangan={pasien.bagian}
            tanggalLahir={pasien.tgl_lahir}
          />
        )}
        {/* Informasi Pasien */}

        {/* Table */}
        {/* Header */}
        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          CAIRAN INTAKE
        </h1>
        <div className='flex'>
          <SimpleColumn name='No' className='text-xs flex-[0.2] ' />
          <SimpleColumn name='Tanggal & Jam' className='text-xs flex-[0.5] ' />
          <SimpleColumn name='Minum' className='text-xs flex-1' />
          <SimpleColumn name='NGT' className='text-xs flex-1' />
          <SimpleColumn name='Infus' className='text-xs flex-1' />
          <SimpleColumn name='Jumlah' className='text-xs flex-1' />
          <SimpleColumn isLast name='Perawat' className='text-xs flex-1' />
        </div>
        {/* Header */}
        {/* Body */}
        {res.intake.map((item, index) => (
          <div key={item.id} className='flex'>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.2]  border-t-0'
            />
            <SimpleColumn
              name={formatDateTime(item.insert_dttm) + ' WIB'}
              className='text-xs flex-[0.5] border-t-0'
            />
            <SimpleColumn
              name={item.minum}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.ngt}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.infuse}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.total}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              isLast
              name='Perawat'
              isChild={
                <div className='flex items-center flex-col'>
                  <QRCode
                    value={item.perawat.nama}
                    className='h-[50px] w-[50px] my-4'
                  />
                  <p className='text-xs'>{item.perawat.nama}</p>
                </div>
              }
              className='text-xs flex-1 border-t-0'
            />
          </div>
        ))}
        {/* Body */}
        {/* Table */}

        {/* Header */}
        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          CAIRAN OUTPUT
        </h1>
        <div className='flex'>
          <SimpleColumn name='No' className='text-xs flex-[0.2] ' />
          <SimpleColumn name='Tanggal & Jam' className='text-xs flex-[0.5] ' />
          <SimpleColumn name='Urine' className='text-xs flex-1' />
          <SimpleColumn name='NGT' className='text-xs flex-1' />
          <SimpleColumn name='WSD' className='text-xs flex-1' />
          <SimpleColumn name='Drain' className='text-xs flex-1' />
          <SimpleColumn name='Muntah' className='text-xs flex-1' />
          <SimpleColumn name='Pendarahan' className='text-xs flex-1' />
          <SimpleColumn name='Jumlah' className='text-xs flex-1' />
          <SimpleColumn isLast name='Perawat' className='text-xs flex-1' />
        </div>
        {/* Header */}
        {/* Table */}
        {res.out_put.map((item, index) => (
          <div key={item.id} className='flex'>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-xs flex-[0.2]  border-t-0'
            />
            <SimpleColumn
              name={formatDateTime(item.insert_dttm) + ' WIB'}
              className='text-xs flex-[0.5] border-t-0'
            />
            <SimpleColumn
              name={item.urine}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.ngt}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.wsd}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.drain}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.muntah}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.pendarahan}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.total}
              className='text-left text-xs flex-1 border-t-0'
            />
            <SimpleColumn
              isLast
              name='Perawat'
              isChild={
                <div className='flex items-center flex-col'>
                  <QRCode
                    value={item.perawat.nama}
                    className='h-[50px] w-[50px] my-4'
                  />
                  <p className='text-xs'>{item.perawat.nama}</p>
                </div>
              }
              className='text-xs flex-1 border-t-0'
            />
          </div>
        ))}
        {/* Table */}

        {/* Header */}
        <h1 className='text-center text-black font-semibold mb-1 mt-4'>
          TRANSFUSI DARAH
        </h1>
        <div className='flex'>
          <SimpleColumn name='No' className='text-xs flex-[0.2] ' />
          <SimpleColumn name='Tanggal & Jam' className='text-xs flex-[0.5] ' />
          <SimpleColumn name='Tanggal Kadaluwarsa' className='text-xs flex-1' />
          <SimpleColumn name='Jenis Darah' className='text-xs flex-1' />
          <SimpleColumn name='Golongan Darah' className='text-xs flex-1' />
          <SimpleColumn name='Jam Pemberian' className='text-xs flex-1' />
          <SimpleColumn name='Nomor Kantong' className='text-xs flex-1' />
          <SimpleColumn name='Volume' className='text-xs flex-1' />
          <SimpleColumn isLast name='Perawat' className='text-xs flex-1' />
        </div>
        {/* Header */}
        {/* Table */}
        {result != null &&
          result.map((item, index) => (
            <div key={item.insert_dttm} className='flex'>
              <SimpleColumn
                name={`${index + 1}`}
                className='text-xs flex-[0.2]  border-t-0'
              />
              <SimpleColumn
                name={formatDateTime(item.insert_dttm) + ' WIB'}
                className='text-xs flex-[0.5] border-t-0'
              />
              <SimpleColumn
                name={formatDate(item.tgl_kadaluwarsa).substring(0, 10)}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                name={item.jenis_darah}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                name={item.gol_darah}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                name={item.jam_pemberian}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                name={item.no_kantung}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                name={`${item.volume} cc`}
                className='text-left text-xs flex-1 border-t-0'
              />
              <SimpleColumn
                isLast
                name='Perawat'
                isChild={
                  <div className='flex items-center flex-col'>
                    <QRCode
                      value={item.perawat}
                      className='h-[50px] w-[50px] my-4'
                    />
                    <p className='text-xs'>{item.perawat}</p>
                  </div>
                }
                className='text-xs flex-1 border-t-0'
              />
            </div>
          ))}
        {/* Table */}
      </div>
    </LayoutBorderNo>
  )
}

export default MonitoringCairan
