import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { DischargePlanning } from '@/models/asesmen-geriatri'
import { getDischargePlanning } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { formatDate } from '@/utils/formatDate'

import { TextTitle } from './text-title'

interface RencanaPemulanganPasienProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  noRm?: string
}

const init: DischargePlanning = {
  insert_dttm: '',
  device: '',
  user_id: '',
  kd_bagian: '',
  noreg: '',
  n1: '',
  n2: '',
  n3: '',
  n4: '',
  n5: '',
  n6: '',
  perawat: '',
  dpjp: '',
  data: {
    diagnosa: '',
    diagnosa_sekunder: '',
    k1: '',
    k2: '',
    k3: '',
    k4: '',
    k5: '',
    keluarga_pasien: '',
  },
  pasien: {
    tgl_lahir: '',
    no_antrean: '',
    jenis_kelamin: '',
    debitur: '',
    kd_debitur: '',
    no_reg: '',
    no_rm: '',
    keterangan: '',
    nama_pasien: '',
    kd_bagian: '',
    nik: '',
    bagian: '',
    pelayanan: '',
    nama_dokter: '',
    kd_dokter: '',
    kamar: '',
    kasur: '',
    asesmen_dokter: '',
    asesmen_perawat: '',
    id: '',
    nama: '',
    agama: '',
    jeniskelamin: '',
    email: '',
    hp: '',
    alamat: '',
    umur: 0,
  },
  tanggal_asesmen: '',
  tanggal_mrs: '',
}

const RencanaPemulanganPasien = ({
  noreg = '',
  noRm = '',
  isReport = false,
}: RencanaPemulanganPasienProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: ['discharge-planning', noreg],
    queryFn: () =>
      getDischargePlanning({
        noreg: noreg!,
        no_rm: noRm,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.perawat == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 13b' rev='01.2020'>
      <div className='p-4'>
        <HeaderFormulir
          nama={res.pasien.nama ?? pasien!.nama_pasien}
          tanggalLahir={res.pasien.tgl_lahir ?? pasien!.tgl_lahir}
          noRm={res.pasien.no_rm ?? pasien!.no_rm}
          nik={res.pasien.nik ?? pasien!.nik}
        >
          <h3>
            PERENCANAAN PEMULANGAN <br />
            PASIEN (DISCHARGE PLANNING) <br />
            RAWAT INAP
          </h3>
        </HeaderFormulir>
        <div className='flex items-center justify-between'>
          <TextTitle
            title={`Tanggal MRS : ${formatDate(res?.tanggal_mrs) ?? ''} WIB `}
          />
          <TextTitle
            title={`Tanggal Pengkajian : ${formatDate(res?.tanggal_asesmen) ?? ''} WIB `}
          />
        </div>
        <div className='mt-4 border border-black p-2'>
          <p className='text-xs'>
            Tujuan : Mempersiapkan kebutuhan pasien saat di rumah atau untuk
            pemulihan dalam 24 jam pertama di ruangan.
          </p>
          <p className='text-xs'>
            Kriteria pasien yang dilakukan Perencanaan Pemulangan (Discharge
            Planning) saat pengkajian awal adalah :
          </p>
          {res.pasien.umur >= 18 ? (
            <div className='ml-2 text-xs font-medium'>
              <p>{res.n1 == 'YA' && 'Umur > 65 Tahun'}</p>
              <p>{res.n2 == 'YA' && 'Keterbatasan Mobilitas'}</p>
              <p>{res.n3 == 'YA' && 'Percobaan Bunuh Diri'}</p>
              <p>{res.n4 == 'YA' && 'Korban atas kasus kriminal'}</p>
              <p>{res.n5 == 'YA' && 'Perawatan atau Pengobatan'}</p>
              <p>
                {res.n5 == 'YA' &&
                  'Bantuan untuk melakukan aktifitas sehari-hari'}
              </p>
            </div>
          ) : (
            <div className='ml-2 text-xs font-medium'>
              <p>{res.n1 == 'YA' && 'Keterbatasan Mobilitas'}</p>
              <p>{res.n2 == 'YA' && 'Percobaan Bunuh Diri'}</p>
              <p>{res.n3 == 'YA' && 'Korban atas kasus kriminal'}</p>
              <p>{res.n4 == 'YA' && 'Perawatan atau Pengobatan'}</p>
              <p>
                {res.n5 == 'YA' &&
                  'Bantuan untuk melakukan aktifitas sehari-hari'}
              </p>
            </div>
          )}

          <div className='mt-4' />
        </div>
        <div className='border border-black border-t-0 p-2'>
          <Text k='Diagnosa' v={res.data.diagnosa} />
          <div className='mt-2' />
          <Text k='Diagnosa Sekunder' v={res.data.diagnosa_sekunder} />
          <div className='flex mt-4'>
            <SimpleColumn
              head
              name='Kebutuhan'
              className='text-xs font-bold flex-1'
            />
            <SimpleColumn
              head
              isLast
              name='Pemenuhan Kebutuhan'
              className='text-xs font-bold flex-1'
            />
          </div>
          <div className='flex'>
            <SimpleColumn
              name='Diperkirakan akan membutuhkan bantuan dalam aktifitas sehari-hari selama di rumah'
              className='text-xs flex-1 border-t-0 text-left'
            />
            <SimpleColumn
              isLast
              name={res.data.k1}
              className='text-xs flex-1 border-t-0 text-left'
            />
          </div>
          <div className='flex'>
            <SimpleColumn
              name='Membutuhkan edukasi gizi yang kompleks terkait penyakitnya'
              className='text-xs flex-1 border-t-0 text-left'
            />
            <SimpleColumn
              isLast
              name={res.data.k2}
              className='text-xs flex-1 border-t-0 text-left'
            />
          </div>
          <div className='flex'>
            <SimpleColumn
              name='Membutuhkan penanganan nyeri kronis'
              className='text-xs flex-1 border-t-0 text-left'
            />
            <SimpleColumn
              isLast
              name={res.data.k3}
              className='text-xs flex-1 border-t-0 text-left'
            />
          </div>
          <div className='flex'>
            <SimpleColumn
              name='Diperkirakan akan membutuhkan pengelolaan penyakit secara berkelanjutan di luar RS. St. Antonio Baturaja.'
              className='text-xs flex-1 border-t-0 text-left'
            />
            <SimpleColumn
              isLast
              name={res.data.k4}
              className='text-xs flex-1 border-t-0 whitespace-pre-wrap'
            />
          </div>
          <div className='flex'>
            <SimpleColumn
              name='Kebutuhan lainnya'
              className='text-xs flex-1 border-t-0 text-left'
            />
            <SimpleColumn
              isLast
              name={res.data.k5}
              className='text-xs flex-1 border-t-0 text-left'
            />
          </div>
        </div>
        {/* DPJP */}
        <div className='p-2 mb-1 m-2 flex items-center justify-evenly'>
          <div className='flex flex-col items-center justify-center gap-4 text-center'>
            {res != null && res.dpjp != '' ? (
              <>
                <div>
                  <p className='text-xs font-semibold'>Dokter</p>
                </div>
                <QRCode value={res.dpjp} className='h-[50px] w-[50px]' />
                <p className='text-xs font-semibold'>({res.dpjp})</p>
              </>
            ) : (
              <div className='h-[100px]' />
            )}
          </div>
          <div className='flex flex-col items-center justify-center gap-4 text-center'>
            {res != null && res.perawat != '' ? (
              <>
                <div>
                  <p className='text-xs font-semibold'>Perawat</p>
                </div>
                <QRCode value={res.perawat} className='h-[50px] w-[50px]' />
                <p className='text-xs font-semibold'>({res.perawat})</p>
              </>
            ) : (
              <div className='h-[100px]' />
            )}
          </div>
          <div className='flex flex-col items-center justify-center gap-4 text-center'>
            {res != null && res.data.keluarga_pasien != '' ? (
              <>
                <div>
                  <p className='text-xs font-semibold'>
                    Keluarga yang menerima
                  </p>
                </div>
                <QRCode
                  value={res.data.keluarga_pasien}
                  className='h-[50px] w-[50px]'
                />
                <p className='text-xs font-semibold'>
                  ({res.data.keluarga_pasien})
                </p>
              </>
            ) : (
              <div className='h-[100px]' />
            )}
          </div>
        </div>
        {/* Perawat */}
      </div>
    </LayoutBorderNo>
  )
}

export default RencanaPemulanganPasien
