import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import Text from '@/components/text'
import { Button } from '@/components/ui/button'
import { DataOperasiByNomor } from '@/models/all-nomor'
import {
  getAllNomorOperasi,
  getPembedahanByNomor,
} from '@/services/laporan-operasi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import Checkbox from '../../../components/checkbox'
import DiagnosaWrapper from './diagnosa-wrapper'
import Item from './item'
import ItemCheckbox from './item-checkbox'

interface OperationReportProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

const OperationReport = ({ isReport, noreg = '' }: OperationReportProps) => {
  const { pasien } = usePasienStore((s) => s)
  const [current, setCurrent] = useState<DataOperasiByNomor | null>(null)
  const [selected, setSelected] = useState('')

  const init: DataOperasiByNomor = {
    pasien: {
      nama: '',
      tgl_lahir: '',
      no_rm: '',
      jenis_kelamin: '',
      alamat: '',
      noreg: '',
      usia: '',
    },
    diagnosa: [],
    data_pembedahaan: {
      tanggal_operasi_id: '',
      tanggal_operasi_id_2: '',
      tanggal_operasi: '',
      tanggal_operasi_2: '',
      klasifikasi: '',
      klasifikasi_luka: '',
      jenis_operasi: '',
      patologi: '',
      uraian: '',
      dimulai: '',
      selesai: '',
      berlangsung: '',
      ada_jaringan: false,
    },
    operator: [],
  }

  const resAllNomor = useQuery({
    queryKey: [constants.queryKey.rekamMedis.allNomorOperasi, noreg],
    queryFn: () =>
      getAllNomorOperasi({
        no_reg: noreg!,
      }).then((res) => {
        const result = res.response.length > 0
        if (result) {
          setSelected(res.response[0].nomor)
        }
        return res
      }),
    enabled: !!noreg,
  })

  const res = resAllNomor != null ? resAllNomor.data?.response : null

  if (resAllNomor.isLoading) return <Loading />
  if (resAllNomor.isError) return <Error />
  if (res?.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const operator = current?.operator
    .filter((i) => i.ket.includes('operator'))
    .map((k) => k.nama)
    .join(', ')

  const instrumen = current?.operator
    .filter((i) => i.ket.includes('instrumen'))
    .map((k) => k.nama)
    .join(', ')

  const anestesi = current?.operator
    .filter((i) => i.ket.includes('anestesi'))
    .map((k) => k.nama)
    .join(', ')

  const asisten = current?.operator
    .filter((i) => i.ket.includes('asisten'))
    .map((k) => k.nama)
    .join(', ')

  const namaPerawat = current?.operator
    .filter((i) => i.ket.includes('perawat'))
    .map((k) => k.nama)
    .join(', ')

  const diagnosaPre =
    current?.diagnosa.filter(
      (i) => i.keterangan == 'icd10' && i.jenis_diag == 'pre',
    ) ?? []

  const diagnosaPost =
    current?.diagnosa.filter(
      (i) => i.keterangan == 'icd10' && i.jenis_diag == 'post',
    ) ?? []

  const tindakan =
    current?.diagnosa.filter(
      (i) => i.keterangan == 'icd9' && i.jenis_diag == 'post',
    ) ?? []

  return (
    <div>
      <ul className='flex mb-4'>
        {res?.map((item, index) => (
          <li className='gap-4 mx-2 ml-2' key={index}>
            <Button
              key={index}
              variant={item.nomor == selected ? 'default' : 'outline'}
              onClick={async () => {
                setSelected(item.nomor)
                const data = await getPembedahanByNomor({
                  no_reg: noreg!,
                  no_rm: pasien!.no_rm,
                  nomor: item.nomor,
                })
                const result = data.response ?? init
                setCurrent(result)
              }}
            >
              {item.nomor}
            </Button>
          </li>
        ))}
      </ul>

      {current != null ? (
        <>
          <LayoutBorderNo isReport={isReport} no='RM 17l' rev='03.2022'>
            <div className='p-4'>
              <HeaderFormulir
                nama={pasien!.nama_pasien}
                tanggalLahir={pasien!.tgl_lahir}
                noRm={pasien!.no_rm}
                nik={pasien!.nik}
              >
                <h3>LAPORAN PEMBEDAHAN</h3>
              </HeaderFormulir>

              {/* Info */}
              <div className='flex gap-4 mt-4'>
                {/* <div className='flex-1'>
                  <Text k='Nama Pasien' v={current.pasien.nama} />
                  <Text k='Tanggal Lahir' v={current.pasien.tgl_lahir} />
                  <Text k='No. Rekam' v={current.pasien.no_rm} />
                </div> */}
                <div className='flex-1'>
                  <Text k='Nama Ahli Bedah' v={operator} />
                  <Text k='Nama Asisten' v={asisten} />
                  <Text k='Nama Instrumen' v={instrumen} />
                  <Text k='Nama Ahli Anastesi' v={anestesi} />
                  <Text k='Nama Perawat' v={namaPerawat} />
                </div>
              </div>
              {/* Info */}

              {/* Table */}
              {/* Header */}
              <div className='flex mt-4'>
                <SimpleColumn
                  name='Tanggal Operasi Dimulai'
                  className='p-[2px] text-xs flex-1 bg-green-200'
                />
                <SimpleColumn
                  name='Tanggal Operasi Selesai'
                  className='p-[2px] text-xs flex-1 bg-green-200'
                />
                <SimpleColumn
                  name='Jam Operasi Dimulai'
                  className='p-[2px] text-xs flex-1 bg-green-200'
                />
                <SimpleColumn
                  name='Jam Operasi Selesai'
                  className='p-[2px] text-xs flex-1 bg-green-200'
                />
                <SimpleColumn
                  isLast
                  name='Lama Operasi Berlangsung'
                  className='p-[2px] text-xs flex-1 bg-green-200'
                />
              </div>
              {/* Header */}

              {/* Body */}
              <div className='flex'>
                <SimpleColumn
                  name={current.data_pembedahaan.tanggal_operasi_id}
                  className='p-[2px] text-xs flex-1 border-t-0'
                />
                <SimpleColumn
                  name={current.data_pembedahaan.tanggal_operasi_id_2}
                  className='p-[2px] text-xs flex-1 border-t-0'
                />
                <SimpleColumn
                  name={current?.data_pembedahaan?.dimulai}
                  className='p-[2px] text-xs flex-1 border-t-0'
                />
                <SimpleColumn
                  name={current?.data_pembedahaan?.selesai}
                  className='p-[2px] text-xs flex-1 border-t-0'
                />
                <SimpleColumn
                  isLast
                  name={current?.data_pembedahaan?.berlangsung}
                  className='p-[2px] text-xs flex-1 border-t-0'
                />
              </div>
              {/* Body */}

              <DiagnosaWrapper title='A. DIAGNOSA PENYAKIT ( ICD 10 ) PRE BEDAH/OPERASI'>
                {diagnosaPre.map((item, idx) => (
                  <Item
                    key={idx}
                    number={`${idx + 1}`}
                    name={`${item.kode} ${item.diagnosa}`}
                  />
                ))}
              </DiagnosaWrapper>

              <DiagnosaWrapper title='B. DIAGNOSA PENYAKIT ( ICD 10 ) POST BEDAH/OPERASI'>
                {diagnosaPost.map((item, idx) => (
                  <Item
                    key={idx}
                    number={`${idx + 1}`}
                    name={`${item.kode} ${item.diagnosa}`}
                  />
                ))}
              </DiagnosaWrapper>

              <DiagnosaWrapper title='C.PROCEDURE - TINDAKAN BEDAH ( ICD 9 )'>
                {tindakan.map((item, idx) => (
                  <Item
                    key={idx}
                    number={`${idx + 1}`}
                    name={`${item.kode} ${item.diagnosa}`}
                  />
                ))}
              </DiagnosaWrapper>

              <div className='border border-t-0 border-black p-2'>
                <ItemCheckbox title='Klasifikasi'>
                  {['ELECTIVE', 'EMERGENCY'].map((i) => (
                    <Checkbox
                      title={i}
                      isChecked={current.data_pembedahaan.klasifikasi == i}
                      key={i}
                    />
                  ))}
                </ItemCheckbox>
                <ItemCheckbox title='Jenis Operasi'>
                  {['KHUSUS', 'BESAR', 'SEDANG', 'KECIL'].map((i) => (
                    <Checkbox
                      title={i}
                      isChecked={current.data_pembedahaan.jenis_operasi == i}
                      key={i}
                    />
                  ))}
                </ItemCheckbox>
                <ItemCheckbox title='Klasifikasi Luka'>
                  {[
                    'BERSIH',
                    'BERSIH TERCEMAR',
                    'TERCEMAR',
                    'KOTOR ATAU DENGAN INFEKSI',
                  ].map((i) => (
                    <Checkbox
                      title={i}
                      isChecked={current.data_pembedahaan.klasifikasi_luka == i}
                      key={i}
                    />
                  ))}
                </ItemCheckbox>
                <ItemCheckbox title='Pengiriman Jaringan'>
                  {['ADA', 'TIDAK ADA'].map((i) => (
                    <Checkbox
                      title={i}
                      isChecked={
                        current.data_pembedahaan.patologi.toUpperCase() == i
                      }
                      key={i}
                    />
                  ))}
                </ItemCheckbox>
              </div>
              {/* Table */}

              <div className='border p-2 border-t-0 border-black bg-green-200'>
                <div>
                  <p className='text-xs'>URAIAN OPERASI</p>
                  <p className='text-xs'>
                    (posisi pasien, sayatan, jaringan yang tampak, kelainan
                    jaringan/organ, jaringan yang dikeluarkan, jahitan,
                    drainage, dan sebagainya)
                  </p>
                </div>
              </div>
              <div className='border border-black p-2 border-t-0 min-h-[100px]'>
                <p className='text-xs whitespace-pre-wrap'>
                  {current.data_pembedahaan.uraian}
                </p>
              </div>
            </div>

            {/* Dokter  */}

            <div className='flex justify-end p-4'>
              <div className='flex flex-col text-center justify-center items-center'>
                <p className='text-xs'>
                  Baturaja, {current.data_pembedahaan.tanggal_operasi}
                </p>
                <QRCode value={operator!} className='h-[50px] w-[50px] my-4' />
                <p className='text-xs underline'>{operator}</p>
                <p className='text-xs'>Dokter Bedah - Operator</p>
              </div>
            </div>

            {/* Dokter  */}
          </LayoutBorderNo>
        </>
      ) : null}
    </div>
  )
}

export default OperationReport
