import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { PemantauanGDSResponse } from '@/models/pemantauan-gds'
import { getPemantauanGds } from '@/services/pemasangan-pemantauan'
import { usePasienStore } from '@/store/pasien.store'
import { formatDate } from '@/utils/formatDate'

interface ReportPemantaunGdsProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  noRm?: string
}

const init: PemantauanGDSResponse = {
  pasien: {
    id: '',
    nik: '',
    nama: '',
    agama: '',
    jeniskelamin: '',
    email: '',
    hp: '',
    tgl_lahir: '',
    alamat: '',
  },
  data: [],
}

const ReportPemantaunGds = ({
  noreg = '',
  noRm = '',
  kdBagian = '',
  isReport = false,
}: ReportPemantaunGdsProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: ['pemantauan-gds', noreg],
    queryFn: () =>
      getPemantauanGds({
        kd_bagian: kdBagian,
        no_reg: noreg!,
        no_rm: noRm,
      }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : init

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.data.length === 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport}>
      <div className='p-4'>
        <HeaderFormulir
          nama={res.pasien.nama ?? pasien!.nama_pasien}
          tanggalLahir={formatDate(res.pasien.tgl_lahir) ?? pasien!.tgl_lahir}
          noRm={res.pasien.id ?? pasien!.no_rm}
          nik={res.pasien.nik ?? pasien!.nik}
        >
          <h3>PEMANTAUAN GULA DARAH SERIAL</h3>
        </HeaderFormulir>
      </div>

      <div className='p-4'>
        {/* header */}
        <div className='text-xs flex'>
          <SimpleColumn head name='Tanggal Pemeriksaan' />
          <SimpleColumn head name='Jam Pemasangan' />
          <SimpleColumn head name='Pemasangan Gula Darah yang Dilakukan' />
          <SimpleColumn head name='Hasil Gula Darah' />
          <SimpleColumn head name='Implementasi Yang Dilakukan' />
          <SimpleColumn head name='Petugas' />
          <SimpleColumn head name='Keterangan' isLast />
        </div>
        {/* header */}

        {/* body */}
        {res.data.map((item, i) => (
          <div className='text-xs flex' key={i}>
            <SimpleColumn className='border-t-0 flex-1' name={item.tanggal} />
            <SimpleColumn className='border-t-0 flex-1' name={item.jam} />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.pemeriksaan}
            />
            <SimpleColumn className='border-t-0 flex-1' name={item.hasil} />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.implementasi}
            />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.keterangan}
            />
            <SimpleColumn
              className='border-t-0 flex-1'
              name={item.perawat}
              hasQR
              isLast
            />
          </div>
        ))}
        {/* body */}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportPemantaunGds
