import { Radiologi } from '@/type'
import { formatDate } from '@/utils/formatDate'

// Item biaya/honor baca radiologi — tidak untuk ditampilkan
const HONOR_RAD_BACA_RE = /Honor\s*Rad\s*Baca\s*RO/i

export function RadiologiTableResume({ data }: { data: Radiologi[] }) {
  const group: Record<string, Radiologi[]> = {}

  for (let i = 0; i < data.length; i++) {
    const curr = data[i]
    const tanggal = formatDate(curr.tanggal)

    if (!group[tanggal]) {
      group[tanggal] = []
    }
    group[tanggal].push(curr)
  }

  const groups = Object.values(group)

  if (groups.length === 0) {
    return (
      <p className='text-xs font-medium text-center'>
        Tidak ada pemeriksaan radiologi
      </p>
    )
  }

  return (
    <div className='border border-black'>
      {groups.map((items, idx) => (
        <div key={idx}>
          <div className='p-1 bg-gray-300'>
            <p className='text-xs'>{formatDate(items[0].tanggal)}</p>
          </div>
          {items.map((item, index) => {
            const pemeriksaanList = item.radiologi.filter(
              (i) => !HONOR_RAD_BACA_RE.test(i.pemeriksaan_deskripsi)
            )
            const kesanList = pemeriksaanList
              .filter((i) => /Kesan\s*:/i.test(i.hasil))
              .map((i) => {
                const match = i.hasil.match(/Kesan\s*:\s*([\s\S]*)/i)
                return { ...i, hasil: match ? match[1].trim() : i.hasil }
              })
            const hasKesan = kesanList.length > 0

            return (
              <div key={`radiologi-${index}`} className='bg-gray-400'>
                <p className='p-2 text-xs font-bold whitespace-pre-wrap'>
                  {pemeriksaanList
                    .map((i) => i.pemeriksaan_deskripsi)
                    .join('\n')}
                </p>
                {hasKesan ? (
                  kesanList.map((p, i) => (
                    <div
                      key={`kesan-${index}-${i}`}
                      className='bg-white border-t border-black'
                    >
                      <div className='border-b border-black'>
                        <h3 className='font-bold py-1 text-xs text-center'>
                          Kesan :
                        </h3>
                      </div>
                      <p className='p-2 text-xs'>{p.hasil}</p>
                    </div>
                  ))
                ) : (
                  <p className='text-xs text-center font-medium bg-white border-t border-black p-2'>
                    Terlampir
                  </p>
                )}
              </div>
            )
          })}
        </div>
      ))}
    </div>
  )
}
