/**
 * Peta form "akhir" (pengkajian akhir / resume akhir di formsTambahan) -> nama form
 * awal yang menjadi parent-nya. Dipakai untuk menyisipkan form akhir tepat di bawah
 * menu awal-nya saat membangun daftar `forms`.
 */
const akhirFormParent: Record<string, string> = {
  'Pengkajian Akhir Medis Ranap': 'Pengkajian Awal Medis RI',
  'Pengkajian Akhir Medis IGD': 'Pengkajian Awal Medis Gawat Darurat',
  'Resume Akhir': 'Ringkasan Pasien Pulang (Discarge Summary) RI',
  'Resume Gawat Darurat Akhir':
    'Ringkasan Pulang (Discarge Summary) Gawat Darurat',
}

// form tambahan kategori "akhir" (disisipkan di bawah parent-nya)
const formsAkhir = formsTambahan.filter((f) => akhirFormParent[f.nama] != null)
// form tambahan lain tetap di akhir daftar
const formsTambahanLain = formsTambahan.filter(
  (f) => akhirFormParent[f.nama] == null,
)

/**
 * Daftar form lengkap dengan urutan:
 * - form awal, diikuti form akhir-nya tepat di bawah
 * - form tambahan lainnya di paling akhir
 */
export const forms: RekamMedisMenu[] = [
  ...[...formsRajal, ...formsRanap].flatMap((f) => [
    f,
    ...formsAkhir.filter((a) => akhirFormParent[a.nama] == f.nama),
  ]),
  ...formsTambahanLain,
]

export const formsRawatJalan = formsRajal
export const formsRawatInap = [...formsRanap, ...formsTambahan]
