import { SimpleColumn } from '@/components/simple-column'
import { DownScore } from '@/models/asesmen-neonatus'

interface DownScoreProps {
  data: DownScore
}

export function DownScoreTable({ data }: DownScoreProps) {
  return (
    <div className='mb-2'>
      <div className='flex'>
        <SimpleColumn
          name='Pembeda'
          className='p-1 flex-1'
          className2='text-xs'
        />
        <SimpleColumn
          isLast
          name='Hasil'
          className='p-1 flex-1'
          className2='text-xs'
        />
      </div>
      {TABLE.map((item, index) => {
        return (
          <div className='flex' key={index}>
            <SimpleColumn
              name={item.col_0}
              className='flex-1 p-1 border-t-0'
              className2='text-xs'
            />
            <SimpleColumn
              isLast
              name={toScore(index, data)}
              className='p-1 flex-1  border-t-0'
              className2='text-xs'
            />
          </div>
        )
      })}
      <span className='text-xs'>{`Keterangan : Skor < 4 = tidak
gawat nafas , Skor 4 – 7 = gawat
nafas
 , Skor > 7 = ancaman gagal nafas`}</span>
    </div>
  )
}

const TABLE = [
  { col_0: 'Frekuensi nafas', col_1: '' },
  { col_0: 'Retraksi dada', col_1: '' },
  { col_0: 'Sianosis', col_1: '' },
  { col_0: 'Air entry', col_1: '' },
  { col_0: 'Merintih', col_1: '' },
  { col_0: 'Total Skor', col_1: '' },
]

const nafas = ["< 60 x/'", "60 - 80 x/'", ">80 x/'"]
const dada = ['Tidak ada', 'Ringan', 'Berat']
const sianosis = [
  'Tidak sianosis ',
  'Hilang dengan O2',
  'Menetap walaupun diberi O2',
]
const airEntry = [
  'Udara masuk bilateral baik',
  'Penurunan ringan udara masuk',
  'Tidak ada udara masuk',
]
const merintih = [
  'Tidak merintih',
  'Terdengar dengan stetoskop',
  'Terdengar tanpa alat bantu',
]

function toScore(index: number, data: DownScore): string {
  switch (index) {
    case 0:
      return nafas[data.nifas]
    case 1:
      return dada[data.retraksi]
    case 2:
      return sianosis[data.sianosis]
    case 3:
      return airEntry[data.air_entry]
    case 4:
      return merintih[data.merintih]
    case 5:
      return `${data.total}`
    default:
      return ''
  }
}
