import type { ReportPermintaanDietModel } from '@/models/permintaan-diet'
import type { Response } from '@/type'

import { post } from './api-2'

const getPermintaanDietReport = async ({
  kd_bagian,
  no_reg,
  no_rm,
}: {
  no_reg: string
  kd_bagian: string
  no_rm: string
}): Promise<Response<ReportPermintaanDietModel>> => {
  const response = await post(`/v1/permintaan-diet-report`, {
    kd_bagian,
    noreg: no_reg,
    no_rm,
  })

  return response.data
}

export { getPermintaanDietReport }
