export default AsesmenAwalKeperawatanRanapAnak

function toCerebral(value: string) {
  switch (value) {
    case '0':
      return 'Mampu merawat diri sendiri secara penuh.'
    case '1':
      return 'Memerlukan penggunaan alat.'
    case '2':
      return 'Memerlukan bantuan atau pengawasan orang lain.'
    case '3':
      return 'Memerlukan bantuan atau pengawasan orang lain dan peralatan'
    case '4':
      return 'Sangat tergantung dan tidak dapat melakukan atau berpartisipasi dalam perawatan'
    default:
      return ''
  }
}

function toKekuatanOtot(value: string) {
  switch (value) {
    case '0':
      return 'Tidak ada kontraksi otot yang terlihat. Pasien tidak mampu menggerakkan otot. Biasanya dialami pasien paralisis otot. Terkadang nyeri dapat mencegah otot untuk berkontraksi.'
    case '1':
      return 'Ada kontraksi otot, tetapi tidak ada gerakan.'
    case '2':
      return 'Otot dapat berkontraksi, tetapi tidak dapat sepenuhnya menggerakkan bagian tubuh melawan gravitasi.'
    case '3':
      return 'Otot dapat berkontraksi sepenuhnya dan menggerakkan bagian tubuh ke segala arah melawan gravitasi. Tetapi ketika diberi tahanan, otot tidak mampu mempertahankan kontraksi.'
    case '4':
      return 'Otot dapat berkontraksi dan memberikan tahanan, akan tetapi  ketika diberi tahanan maksimal, otot tidak mampu mempertahankan kontraksi.'
    case '5':
      return 'Otot berfungsi normal dan dapat mempertahankan posisinya ketika diberi tahanan maksimal'
    default:
      return ''
  }
}
