import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import type {
  AsesmenPraAnestesi,
  AsesmenPraInduksi,
  AsesmenPraSedasi,
} from '@/models/asesmen-pra-varian'
import {
  getAsesmenPraAnestesi,
  getAsesmenPraInduksi,
  getAsesmenPraSedasi,
} from '@/services/asesmen-pra-varian'
import { usePasienStore } from '@/store/pasien.store'
import type { Response } from '@/type'
import { constants } from '@/utils/constants'
import { formatDate, formatDateTime } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportAsesmenPraVarianProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
  jenis: 'anestesi' | 'sedasi' | 'induksi'
}

const INIT_ANESTESI: AsesmenPraAnestesi = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  pelayanan: '',
  insert_user_id: '',
  riwayat_penyakit_dahulu: '',
  td: '',
  nadi: '',
  rr: '',
  suhu: '',
  bb: '',
  tb: '',
  riwayat_penggunaan_obat: '',
  perokok: '',
  riwayat_anestesi: '',
  riwayat_alergi: '',
  persiapan_transfusi: '',
  mulut: '',
  tenggorokan: '',
  gigi: '',
  ekstremitas: '',
  jantung: '',
  paru_paru: '',
  abdomen: '',
  lain_lain: '',
  laboratorium: '',
  ekg: '',
  thorak: '',
  pp_lain: '',
  klasifikasi_asa: '',
  rencana_anestesi: '',
  instruksi_pra_anestesi: '',
  user: '',
}

const INIT_SEDASI: AsesmenPraSedasi = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  pelayanan: '',
  insert_user_id: '',
  riwayat_penyakit_dahulu: '',
  td: '',
  nadi: '',
  rr: '',
  suhu: '',
  bb: '',
  tb: '',
  riwayat_penggunaan_obat: '',
  perokok: '',
  riwayat_anestesi: '',
  riwayat_alergi: '',
  persiapan_transfusi: '',
  mulut: '',
  tenggorokan: '',
  gigi: '',
  ekstremitas: '',
  jantung: '',
  paru_paru: '',
  abdomen: '',
  lain_lain: '',
  laboratorium: '',
  ekg: '',
  thorak: '',
  klasifikasi_asa: '',
  rencana_sedasi: '',
  instruksi_pra_sedasi: '',
  user: '',
}

const INIT_INDUKSI: AsesmenPraInduksi = {
  id: 0,
  insert_dttm: '',
  noreg: '',
  kd_bagian: '',
  pelayanan: '',
  insert_user_id: '',
  td: '',
  nadi: '',
  rr: '',
  suhu: '',
  riwayat_anestesi: '',
  riwayat_alergi: '',
  persiapan_transfusi: '',
  mulut: '',
  tenggorokan: '',
  jantung: '',
  paru_paru: '',
  abdomen: '',
  lain_lain: '',
  laboratorium: '',
  ekg: '',
  thorak: '',
  klasifikasi_asa: '',
  rencana_anestesi: '',
  rencana_pemulihan_pasca: '',
  user: '',
}

type PraVarianData = Partial<AsesmenPraAnestesi> &
  Partial<AsesmenPraSedasi> &
  Partial<AsesmenPraInduksi>

const ReportAsesmenPraVarian = ({
  isReport,
  noreg,
  kdBagian,
  jenis,
}: ReportAsesmenPraVarianProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenPraBedah, noreg, jenis],
    queryFn: () => {
      if (jenis == 'anestesi')
        return getAsesmenPraAnestesi(noreg!, kdBagian!) as Promise<
          Response<PraVarianData>
        >
      if (jenis == 'sedasi')
        return getAsesmenPraSedasi(noreg!, kdBagian!) as Promise<
          Response<PraVarianData>
        >
      return getAsesmenPraInduksi(noreg!, kdBagian!) as Promise<
        Response<PraVarianData>
      >
    },
    enabled: !!noreg,
  })

  const res: PraVarianData =
    data != null
      ? data.response
      : jenis == 'anestesi'
        ? INIT_ANESTESI
        : jenis == 'sedasi'
          ? INIT_SEDASI
          : INIT_INDUKSI

  const judul =
    jenis == 'anestesi'
      ? 'PENGKAJIAN PRA ANESTESI'
      : jenis == 'sedasi'
        ? 'PENGKAJIAN PRA SEDASI'
        : 'PENGKAJIAN PRE INDUKSI'

  const noRm =
    jenis == 'anestesi' ? 'RM 17e' : jenis == 'sedasi' ? 'RM 17f' : 'RM 17g'

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.noreg == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no={noRm} rev='01.2020'>
      <div className='p-4 text-xs'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-xs font-bold text-center py-3'>{judul}</h3>
        </HeaderFormulir>

        <div className='flex p-2'>
          <p className='text-xs text-black'>
            Tanggal Pengkajian : {formatDateTime(res.insert_dttm ?? '')} WIB
          </p>
        </div>

        <div className='gap-4 border border-black p-1 mb-1'>
          <div className='mb-4'>
            <TextField title='TD' value={res.td} />
            <TextField title='Nadi' value={res.nadi} />
            <TextField title='RR' value={res.rr} />
            <TextField title='Suhu' value={res.suhu} />
            {jenis != 'induksi' && (
              <>
                <TextField title='BB' value={res.bb} />
                <TextField title='TB' value={res.tb} />
                <TextField title='Riwayat Penyakit Dahulu' value={res.riwayat_penyakit_dahulu} />
                <TextField title='Riwayat Penggunaan Obat' value={res.riwayat_penggunaan_obat} />
                <TextField title='Perokok' value={res.perokok} />
              </>
            )}
            <TextField title='Riwayat Anestesi' value={res.riwayat_anestesi} />
            <TextField title='Riwayat Alergi' value={res.riwayat_alergi} />
            <TextField title='Persiapan Transfusi' value={res.persiapan_transfusi} />
            <TextField title='Mulut' value={res.mulut} />
            <TextField title='Tenggorokan' value={res.tenggorokan} />
            {jenis != 'induksi' && <TextField title='Gigi' value={res.gigi} />}
            {jenis != 'induksi' && <TextField title='Ekstremitas' value={res.ekstremitas} />}
            <TextField title='Jantung' value={res.jantung} />
            <TextField title='Paru-Paru' value={res.paru_paru} />
            <TextField title='Abdomen' value={res.abdomen} />
            <TextField title='Lain-lain' value={res.lain_lain} />
            <TextField title='Laboratorium' value={res.laboratorium} />
            <TextField title='EKG' value={res.ekg} />
            <TextField title='Thorak' value={res.thorak} />
            {jenis == 'anestesi' && <TextField title='PP Lain' value={res.pp_lain} />}
            <TextField title='Klasifikasi ASA' value={res.klasifikasi_asa} />
            <TextField
              title='Rencana'
              value={
                jenis == 'anestesi'
                  ? res.rencana_anestesi
                  : jenis == 'sedasi'
                    ? res.rencana_sedasi
                    : res.rencana_anestesi
              }
            />
            {jenis == 'induksi' && (
              <TextField
                title='Rencana Pemulihan Pasca'
                value={res.rencana_pemulihan_pasca}
              />
            )}
            <TextField
              title='Instruksi'
              value={
                jenis == 'anestesi'
                  ? res.instruksi_pra_anestesi
                  : jenis == 'sedasi'
                    ? res.instruksi_pra_sedasi
                    : ''
              }
            />
          </div>
        </div>
        {/* Tanda Tangan */}
        <div className='ml-4'>
          <div className='py-10' />
          <div className='flex items-end justify-between'>
            <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
              <p className='font-medium'>
                Baturaja, {formatDate(res.insert_dttm ?? '')}
              </p>
              {res.user ? (
                <>
                  <QRCode value={res.user} className='h-[50px] w-[50px]' />
                  <p>( {res.user} )</p>
                </>
              ) : (
                <div className='h-[50px]' />
              )}
            </div>
          </div>
        </div>
        {/* Tanda Tangan */}
      </div>
    </LayoutBorderNo>
  )
}

export default ReportAsesmenPraVarian
