import { List, Table as TableIcon } from 'lucide-react'

import { useState } from 'react'

import { Button } from '@/components/ui/button'
import { ObatSelamaRanap } from '@/models/resume-pulang-ranap'

type ViewMode = 'table' | 'list'

function renderObatTable(items: string[]) {
  const rows = []
  for (let i = 0; i < items.length; i += 3) {
    rows.push(items.slice(i, i + 3))
  }

  return (
    <table className='w-full mb-2 border border-black border-collapse'>
      <tbody>
        {rows.map((row, i) => (
          <tr key={i}>
            {row.map((text, j) => (
              <td
                key={j}
                className='text-xs uppercase align-top whitespace-normal border border-black px-1'
              >
                {text}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}

function renderObatList(items: string[]) {
  return (
    <ul className='w-full mb-2 list-none'>
      {items.map((text, i) => (
        <li key={i} className='text-xs uppercase py-1'>
          {text}
        </li>
      ))}
    </ul>
  )
}

// toggle tampilan tabel / list
function ViewToggle({
  mode,
  onChange,
}: {
  mode: ViewMode
  onChange: (mode: ViewMode) => void
}) {
  return (
    <div className='flex items-center gap-1 mb-1 w-max print:hidden'>
      <Button
        type='button'
        size='sm'
        variant={mode == 'table' ? 'default' : 'outline'}
        className='h-6 px-2 text-[10px]'
        onClick={() => onChange('table')}
      >
        <TableIcon className='h-3 w-3' /> Tabel
      </Button>
      <Button
        type='button'
        size='sm'
        variant={mode == 'list' ? 'default' : 'outline'}
        className='h-6 px-2 text-[10px]'
        onClick={() => onChange('list')}
      >
        <List className='h-3 w-3' /> List
      </Button>
    </div>
  )
}

export function ObatTable({
  data,
}: {
  isRanap?: boolean
  data: ObatSelamaRanap[]
}) {
  const [mode, setMode] = useState<ViewMode>('table')

  if (data.length > 0) {
    // flatten items: multi-line `catatan` dipecah per baris jadi satu item
    const items: string[] = []
    data.forEach((item) => {
      if (item.nama_obat == '') {
        item.catatan
          .split('\n')
          .map((line) => line.trim())
          .filter((line) => line != '')
          .forEach((line) => items.push(line))
      } else {
        items.push(`${item.nama_obat} ${item.dosis} ${item.cara}`.trim())
      }
    })

    const list = dedupeItems(items)

    return (
      <>
        <ViewToggle mode={mode} onChange={setMode} />
        {mode == 'table' ? renderObatTable(list) : renderObatList(list)}
      </>
    )
  } else {
    return (
      <p className='text-xs text-center font-medium'>
        {/* Tidak ada obat {isRanap ? 'selama dirawat' : 'yang dibawa pulang'} */}
      </p>
    )
  }
}

// ambil nama obat: token-token awal sebelum token yang mengandung angka (dosis/satuan)
function extractObatName(line: string): string {
  const cleaned = line.trim().replace(/^[\s\-•*()]+/, '')
  const name: string[] = []
  for (const token of cleaned.split(/\s+/)) {
    if (/\d/.test(token)) break
    name.push(token)
  }
  return (name.join(' ') || cleaned).toLowerCase()
}

// item dengan nama yang sama tidak di-render ulang
function dedupeItems(items: string[]): string[] {
  const seen = new Set<string>()
  const result: string[] = []
  for (const line of items) {
    const key = extractObatName(line)
    if (!seen.has(key)) {
      seen.add(key)
      result.push(line)
    }
  }
  return result
}

export function ObatTableText({ text }: { text: string }) {
  const [mode, setMode] = useState<ViewMode>('table')

  const items = text
    .split('\n')
    .map((line) => line.trim())
    .filter((line) => line != '')

  const list = dedupeItems(items)

  if (list.length == 0) return null

  return (
    <>
      <ViewToggle mode={mode} onChange={setMode} />
      {mode == 'table' ? renderObatTable(list) : renderObatList(list)}
    </>
  )
}
