import { SimpleColumn } from '@/components/simple-column'
import { cn } from '@/lib/utils'
import { InstruksiPengantarRawatInap } from '@/type'

export function InstruksiTable({
  data,
}: {
  data: InstruksiPengantarRawatInap[]
}) {
  if (data.length > 0) {
    return (
      <div className='mb-2'>
        <div className='flex'>
          <SimpleColumn
            head
            name='No.'
            className='w-[50px] p-1 border-b-0'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Tanggal'
            className='p-1 flex-1 border-b-0'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Nama Obat'
            className='p-1 flex-1 border-b-0'
            className2='text-xs'
          />
          <SimpleColumn
            head
            name='Jumlah'
            className='p-1 flex-1 border-b-0'
            isLast
            className2='text-xs'
          />
        </div>
        {data != null &&
          data.length > 0 &&
          data.map((item, i) => (
            <div className='flex' key={i}>
              <SimpleColumn
                name={`${i + 1}`}
                className={cn(
                  `w-[50px] p-1`,
                  data.length - 1 != i ? 'border-b-0' : '',
                )}
                className2='text-xs'
              />
              <SimpleColumn
                name={item.tgl_keluar}
                className={cn(
                  'p-1 flex-1 items-start',
                  data.length - 1 != i ? 'border-b-0' : '',
                )}
                className2='text-xs'
              />
              <SimpleColumn
                name={`${item.nama_obat}`}
                className={cn(
                  'p-1 flex-1 items-start',
                  data.length - 1 != i ? 'border-b-0' : '',
                )}
                className2='text-xs'
              />
              <SimpleColumn
                name={`${item.jumlah}`}
                className={cn(
                  'p-1 flex-1 items-start',
                  data.length - 1 != i ? 'border-b-0' : '',
                )}
                isLast
                className2='text-xs capitalize'
              />
            </div>
          ))}
      </div>
    )
  } else {
    return (
      <p className='text-xs text-center font-medium'>Tidak ada instruksi</p>
    )
  }
}
