import { Fragment, useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { ResikoJatuhMorse } from '@/models/resiko-jatuh'
import { getAllResikoJatuhMorse } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPengkajianUlangResikoJatuhDewasaProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

// Skala Morse Falls Scale (MFS) sesuai layout Flutter
type SkalaMorse = {
  title: string
  skor: number
  selected: boolean
}

type FaktorMorse = {
  title: string
  skala: SkalaMorse[]
}

const buildFaktor = (data: ResikoJatuhMorse): FaktorMorse[] => {
  const contains = (val: string, keys: string[]) =>
    keys.some((k) => val.includes(k))

  return [
    {
      title: 'Riwayat Jatuh',
      skala: [
        { title: 'Ya', skor: 25, selected: contains(data.r_jatuh, ['Ya']) },
        {
          title: 'Tidak',
          skor: 0,
          selected: contains(data.r_jatuh, ['Tidak']),
        },
      ],
    },
    {
      title: 'Diagnosis sekunder (>= 2 diagnosis medis)',
      skala: [
        { title: 'Ya', skor: 15, selected: contains(data.diagnosis, ['Ya']) },
        {
          title: 'Tidak',
          skor: 0,
          selected: contains(data.diagnosis, ['Tidak']),
        },
      ],
    },
    {
      title: 'Bantuan Ambulasi',
      skala: [
        {
          title: 'Furniture : dinding, meja, kursi, lemari',
          skor: 30,
          selected: contains(data.ambulasi, ['Furniture', 'dinding', 'meja']),
        },
        {
          title: 'Kruk / Tongkat / Walker',
          skor: 15,
          selected: contains(data.ambulasi, ['Kruk', 'Tongkat', 'Walker']),
        },
        {
          title: 'Di tempat tidur / butuh bantuan perawat / memakai kursi roda',
          skor: 0,
          selected: contains(data.ambulasi, [
            'tempat tidur',
            'kursi roda',
            'bantuan perawat',
          ]),
        },
      ],
    },
    {
      title: 'Terpasang infuse',
      skala: [
        {
          title: 'Ya',
          skor: 20,
          selected: contains(data.terpasang_infuse, ['Ya']),
        },
        {
          title: 'Tidak',
          skor: 0,
          selected: contains(data.terpasang_infuse, ['Tidak']),
        },
      ],
    },
    {
      title: 'Gaya berjalan',
      skala: [
        {
          title: 'Terganggu',
          skor: 20,
          selected: contains(data.gaya_berjalan, ['Terganggu']),
        },
        {
          title: 'Lemah',
          skor: 10,
          selected: contains(data.gaya_berjalan, ['Lemah']),
        },
        {
          title: 'Normal / tirah baring / imobilisasi',
          skor: 0,
          selected: contains(data.gaya_berjalan, [
            'Normal',
            'tirah baring',
            'imobilisasi',
          ]),
        },
      ],
    },
    {
      title: 'Status mental',
      skala: [
        {
          title: 'Sering lupa akan keterbatasan yang dimiliki',
          skor: 15,
          selected: contains(data.status_mental, ['Sering lupa']),
        },
        {
          title: 'Sadar akan kemampuan diri sendiri',
          skor: 0,
          selected: contains(data.status_mental, ['Sadar']),
        },
      ],
    },
  ]
}

const ReportPengkajianUlangResikoJatuhDewasa = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangResikoJatuhDewasaProps) => {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.resikoJatuhMorse, noreg],
    queryFn: () =>
      getAllResikoJatuhMorse({ noReg: noreg!, kdBagian: kdBagian! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const Default = () => {
    const d = res[index]
    const faktor = buildFaktor(d)

    return (
      <LayoutBorderNo isReport={isReport} no='RM RI 38' rev='01.2020'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-2'>
              PENGKAJIAN ULANG RESIKO JATUH PADA PASIEN DEWASA
            </h3>
          </HeaderFormulir>

          <p className='text-justify text-black my-2'>
            Lakukan pengkajian (skoring) risiko jatuh pada saat terjadi
            perubahan kondisi pasien/therapi, saat pasien pindah ruangan lain,
            pasien risiko tinggi dikaji setiap 24 jam atau sesaat terjadi kasus
            jatuh.
          </p>

          {/* Header tabel */}
          <table className='w-full text-xs table-fixed border-collapse'>
            <colgroup>
              <col />
              <col />
              <col style={{ width: 70 }} />
              <col style={{ width: 110 }} />
            </colgroup>
            <thead>
              <tr className='font-bold text-center'>
                <th className='border border-black p-2'>Faktor Resiko</th>
                <th className='border border-black p-2'>SKALA</th>
                <th className='border border-black p-2'>POIN</th>
                <th className='border border-black p-2'>Tgl / Pukul</th>
              </tr>
            </thead>
            <tbody>
              {faktor.map((f, fi) => (
                <Fragment key={fi}>
                  {f.skala.map((s, si) => (
                    <tr key={si}>
                      {si === 0 && (
                        <td
                          rowSpan={f.skala.length}
                          className='border border-black p-2 align-middle'
                        >
                          {f.title}
                        </td>
                      )}
                      <td
                        className={cn(
                          'border border-black p-2 align-middle',
                          s.selected && 'bg-green-200',
                        )}
                      >
                        {s.title}
                      </td>
                      <td className='border border-black p-2 text-center'>
                        {s.skor}
                      </td>
                      <td className='border border-black p-2 text-center'>
                        {s.selected ? '✓' : ''}
                      </td>
                    </tr>
                  ))}
                </Fragment>
              ))}
            </tbody>
            <tfoot>
              <tr className='font-bold'>
                <td colSpan={2} className='border border-black p-2 text-right'>
                  TOTAL
                </td>
                <td colSpan={2} className='border border-black p-2 text-center'>
                  {d.total}
                </td>
              </tr>
            </tfoot>
          </table>

          <p className='text-black mt-3 whitespace-pre-wrap'>
            {`Keterangan :
⚫ Tulis jumlah skor yang sesuai pada kolom skor pasien
⚫ Kategori :
   - Resiko rendah  : 0 - 24
   - Resiko sedang : 25 - 44
   - Resiko tinggi    : >= 45`}
          </p>

          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />
            <div className='flex items-end justify-center'>
              <div className='flex flex-col items-center text-center'>
                <p className='font-medium'>
                  Baturaja, {formatDateTime(d.insertDttm)} WIB
                </p>
                <p className='font-medium mb-4'>Perawat</p>
                <QRCode
                  value={d.nama_perawat ?? '-'}
                  className='w-[50px] h-[50px]'
                />
                <p className='mt-4'>
                  ({d.nama_perawat || '.........................'})
                </p>
              </div>
            </div>
          </div>
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {res != null &&
        res.length > 0 &&
        res.map((d, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatDateTime(d.insertDttm)}
          </Button>
        ))}

      {res.length > 0 && <Default />}
    </>
  )
}

export default ReportPengkajianUlangResikoJatuhDewasa
