interface ReportResumeProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

interface ResumeContentProps {
  isReport?: boolean
  no?: string
  res: RingkasanPerawatanPasienPulang
  data: ResumePulangRanap
}

function ResumeContent({
  isReport = false,
  no,
  res,
  data,
}: ResumeContentProps) {
  // regex meninggal
  const regex = /Meninggal/
  const isMeninggal = regex.test(data.tindak_lanjut.kondisi_pulang)
  const penyebabDiagnosa = data.penyebab.filter((i) => i.kode != '')

  return (
    <LayoutBorderNo isReport={isReport} no={no} rev='04.2020'>
      <div className='p-1'>
        <HeaderFormulir
          nama={res?.nama_pasien ?? ''}
          tanggalLahir={res?.tanggal_lahir ?? ''}
          noRm={res?.no_rm ?? ''}
          nik={res?.nik ?? ''}
        >
          <h3>RINGKASAN PASIEN PULANG</h3>
          <h3>(DISCHARGE SUMMARY) RAWAT INAP</h3>
        </HeaderFormulir>

        <div className='flex items-center justify-between'>
          <TextTitle
            title={`Tanggal Masuk : ${formatDate(res?.tgl_masuk) ?? res?.tgl_masuk}`}
          />
          <TextTitle
            title={`Tanggal Keluar : ${formatDate(res?.tgl_keluar) ?? res?.tgl_keluar}`}
          />
        </div>

        <div className='flex items-center gap-4 border border-black p-1 mb-1'>
          <div className='flex-1'>
            <TextTitle title='Anamnesa' />
            {/* TODO */}
            <p className='text-xs'>
              Indikasi Rawat Inap : {data.indikasi_ranap.keluhan_utama}
            </p>
            <p className='text-xs'>
              Riwayat Kesehatan :{' '}
              {data.indikasi_ranap.riwayat_penyakit_sekarang}
            </p>
            <div className='mt-4' />
            <TextTitle title='Pemeriksaan Fisik' />
            <div className='flex gap-20'>
              {renderPemeriksaanFisik(data.indikasi_ranap)}
              <div className='flex-1'>
                <TextTitle title='Tanda Tanda Vital' />
                <TextField title='TD' value={`${data.vital_sign.td} mm Hg`} />
                <TextField
                  title='Nadi'
                  value={`${data.vital_sign.nadi} / menit`}
                />
                <TextField title='Suhu' value={`${data.vital_sign.suhu} °C`} />
                <TextField
                  title='Pernafasan'
                  value={`${data.vital_sign.pernafasan} x / menit`}
                />
                <TextField title='SpO2' value={`${data.vital_sign.spo2} %`} />
              </div>
            </div>

            <MarginWrapper>
              <TextTitle title='Pemeriksaan Diagnostik' />
              <div>
                {data.labor.length == 0 && (
                  <TextField
                    title='Laboratorium'
                    value={data.pemeriksaan_diagnostik.laboratorium}
                  />
                )}
                {data.radiologi.length == 0 && (
                  <TextField
                    title='Radiologi'
                    value={data.pemeriksaan_diagnostik.radiologi}
                  />
                )}
                <TextField title='PA' value={data.pemeriksaan_diagnostik.pa} />
                <TextField
                  title='Lainnya'
                  value={data.pemeriksaan_diagnostik.lainnya}
                />
              </div>
            </MarginWrapper>

            <MarginWrapper>
              <TextTitle title='Diagnosa (ICD-10)' />
              <DiagnosaTable data={data.diagnosa} />
              <TextTitle
                title={penyebabDiagnosa.length > 0 ? 'Penyebab Diagnosa' : ''}
              />
              <PenyebabTable data={penyebabDiagnosa} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Tindakan (ICD-9)' />
              <TindakanTable data={data.tindakan} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Laboratorium' />
              <LaborTableResume data={data.labor} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Pemeriksaan Lain' />
              <RadiologiTableResume data={data.radiologi} />
            </MarginWrapper>
            {/* {SCREEN_HEIGHT > 1122 && <div className='pt-[80px]' />} */}
            <MarginWrapper>
              <TextTitle title='Obat yang diberikan' />
              <ObatTable isRanap data={data.obat_selama_ranap ?? []} />
            </MarginWrapper>
            <MarginWrapper>
              <TextTitle title='Obat yang dibawa pulang' />
              <ObatTable data={data.obat_dibawa_pulang ?? []} />
            </MarginWrapper>
            <div>
              <TextTitle title='Kondisi kesehatan pasien saat akan pulang' />
              <TextField
                title={data.tindak_lanjut.kondisi_pulang ?? '-'}
                value=''
              />
            </div>
            <div>
              <TextTitle title='Keadaan Pulang' />
              <TextField
                title={data.tindak_lanjut.cara_keluar ?? '-'}
                value=''
              />
            </div>
            <div>
              <TextTitle title='Instruksi Tindak Lanjut (Follow Up)' />
              <TextField
                title='Tujuan Rujuk'
                value={data.tindak_lanjut.cara_keluar_detail ?? '-'}
              />
              <TextField
                title='Alasan Rujuk'
                value={data.tindak_lanjut.asesmed_alasan_rujuk ?? '-'}
              />
              <TextField
                title='Kontrol'
                value={data.tindak_lanjut.bagian != '' ? 'YA' : 'TIDAK'}
              />
              <TextField
                title='Tujuan Selanjutnya'
                value={data.tindak_lanjut.bagian}
              />
              <TextField
                title='Dokter Selanjutnya'
                value={data.tindak_lanjut.nama_dokter}
              />
              <TextField
                title='Tanggal Kontrol'
                value={
                  data.tindak_lanjut.kontrol_tanggal == '' ||
                  data.tindak_lanjut.kontrol_tanggal.startsWith('0')
                    ? ''
                    : formatDate(data.tindak_lanjut.kontrol_tanggal)
                }
              />
              <TextField
                title='Catatan / Edukasi'
                value={data.tindak_lanjut.instruksi_tindak_lanjut}
              />
            </div>
          </div>
        </div>

        <MarginWrapper>
          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-4' />
            <div className='flex items-end justify-between'>
              <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
                {res != null && res.nama_pasien != '' ? (
                  <>
                    <p className='text-xs font-medium'>
                      {isMeninggal
                        ? data.indikasi_ranap.image_url != ''
                          ? 'Keluarga'
                          : ''
                        : 'Pasien'}
                    </p>
                    {res.nama_pasien != '' && !isMeninggal ? (
                      data.indikasi_ranap.image_url != '' ? (
                        <img
                          alt='ttd'
                          src={`${import.meta.env.VITE_BASE_API_URL_RME}/app/images/ttd/${data.indikasi_ranap.image_url}`}
                          className='h-[100px] w-[100px] object-contain'
                        />
                      ) : (
                        <QRCode
                          value={res.nama_pasien}
                          className='h-[50px] w-[50px]'
                        />
                      )
                    ) : (
                      <div className='h-[50px]' />
                    )}
                    <p className='text-xs'>
                      {isMeninggal
                        ? '...............................................'
                        : data.indikasi_ranap.image_url == ''
                          ? `( ${res.nama_pasien} )`
                          : ''}{' '}
                    </p>
                  </>
                ) : (
                  <div className='h-[100px]' />
                )}
              </div>
              {/*  */}
              <div className='w-full text-center items-center flex flex-col gap-4'>
                {res != null && data.indikasi_ranap.perawat_edukasi != '' ? (
                  <>
                    <p className='text-xs font-medium'>Petugas Yang Merawat</p>
                    {data.indikasi_ranap.perawat_edukasi != null ? (
                      <QRCode
                        value={data.indikasi_ranap.perawat_edukasi}
                        className='h-[50px] w-[50px]'
                      />
                    ) : (
                      <div className='h-[100px]' />
                    )}
                    <p className='text-xs'>
                      ( {data.indikasi_ranap.perawat_edukasi} )
                    </p>
                  </>
                ) : (
                  <div className='h-[100px]' />
                )}
              </div>
              {/*  */}
              <div className='w-full text-center items-center flex flex-col gap-4'>
                <p className='text-xs'>
                  Baturaja, {dayjs(res!.tgl_keluar).format('DD/MM/YY')}{' '}
                  {res!.jam_keluar}
                </p>

                {res != null && data.indikasi_ranap.dpjp != '' ? (
                  <>
                    <p className='text-xs font-medium'>Dokter Yang Merawat</p>
                    {data.indikasi_ranap.dpjp != null ? (
                      <QRCode
                        value={data.indikasi_ranap.dpjp}
                        className='h-[50px] w-[50px]'
                      />
                    ) : (
                      <div className='h-[100px]' />
                    )}
                    <p className='text-xs'>( {data.indikasi_ranap.dpjp} )</p>
                  </>
                ) : (
                  <div className='h-[100px]' />
                )}
              </div>
            </div>
          </div>
        </MarginWrapper>
      </div>
    </LayoutBorderNo>
  )
}

export default function ReportResume({
  isReport = false,
  noreg = '',
  no,
  kdBagian,
}: ReportResumeProps) {
  const { res, isLoading, isError, resRanap, resumeRanapAll } = useReportResume(
    noreg,
    kdBagian!,
    'AWAL',
  )

  const [current, setCurrent] = useState<ResumePulangRanap | null>(null)
  const [index, setIndex] = useState(0)

  useEffect(() => {
    if (resumeRanapAll != null && resumeRanapAll.data != null) {
      const data = resumeRanapAll.data.response
      if (data.length > 0) {
        setCurrent(data[index])
      }
    }
  }, [index, resumeRanapAll])

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res?.no_register == '')
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  // default: pakai elemen pertama array; fallback ke resRanap jika array kosong
  const activeData = current ?? resumeRanapAll?.data?.response?.[0] ?? resRanap

  return (
    <>
      {resumeRanapAll != null &&
        resumeRanapAll.data != null &&
        resumeRanapAll.data.response.length > 0 &&
        resumeRanapAll.data?.response.map((item, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setCurrent(item)
              setIndex(idx)
            }}
          >
            {idx + 1}
          </Button>
        ))}

      <ResumeContent isReport={isReport} no={no} res={res} data={activeData} />
    </>
  )
}

function renderPemeriksaanFisik(data: IndikasiRanap) {
  return match(data.insert_user_spesialis)
    .with('MATA', () => <PemeriksaanFisikMataResume data={data} />)
    .with('THT', () => <PemeriksaanFisikThtResume data={data} />)
    .otherwise(() => (
      <PemeriksaanFisikDefault
        kepala={data.kepala_dan_leher}
        anggotaGerak={data.anggota_gerak}
        dada={data.dada}
        genetalia={data.genetalia_dan_anus}
        perut={data.perut_dan_pinggang}
      />
    ))
}
