/** Judul tiap komponen per metode (untuk tabel di laporan). */
export function nyeriComponentTitles(metode: string): string[] {
  if (metode === 'NIPS') {
    return [
      'Ekspresi Wajah',
      'Menangis',
      'Pola Napas',
      'Lengan',
      'Kaki',
      'Keadaan Rangsangan',
      'Heart Rate',
      'Saturasi O2',
    ]
  }
  if (metode === 'FLACGS' || metode === 'FLACC') {
    return ['Face', 'Leg', 'Activity', 'Cry', 'Consolability']
  }
  if (metode === 'CONFORT_SCALE' || metode === 'COMFORT SCALE') {
    return [
      'Kewaspadaan',
      'Ketenangan',
      'Distres Napas',
      'Menangis',
      'Pergerakan',
      'Tonus Otot',
      'Tegangan Wajah',
      'Tekanan Darah Basal',
      'Denyut Jantung Basal',
    ]
  }
  return []
}

/** Mapping skor -> gambar wajah (mirror Flutter FormWidget.toNyeri). */
export function toNyeriImage(skorNyeri: number): string {
  const { an1, an2, an3, an4, an5, an6 } = images.asesmenNyeri
  if (skorNyeri === 1) return an1
  if (skorNyeri <= 3) return an2
  if (skorNyeri <= 5) return an3
  if (skorNyeri === 6) return an4
  if (skorNyeri <= 8) return an5
  return an6
}

/** Mapping skor -> teks keterangan nyeri (mirror Flutter FormWidget.toNyeriText). */
export function toNyeriText(skorNyeri: number): string {
  if (skorNyeri === 1) return 'Tidak Ada Nyeri'
  if (skorNyeri <= 3) return 'Nyeri Ringan'
  if (skorNyeri <= 5) return 'Nyeri Yang Mengganggu'
  if (skorNyeri <= 7) return 'Nyeri Yang Menyusahkan'
  if (skorNyeri <= 9) return 'Nyeri Hebat'
  return 'Nyeri Sangat Hebat'
}
