import { Fragment, useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { cn } from '@/lib/utils'
import { ReAsesmenResikoJatuhAnak } from '@/models/resiko-jatuh'
import { getAllReAsesmenResikoJatuhAnak } from '@/services/asesmen-keperawatan'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

interface ReportPengkajianUlangResikoJatuhAnakProps {
  isReport?: boolean
  noreg?: string
  kdBagian?: string
}

type SkalaAnak = {
  title: string
  skor: number
  selected: boolean
}

type FaktorAnak = {
  faktor: string
  risiko: SkalaAnak[]
}

const buildFaktor = (data: ReAsesmenResikoJatuhAnak): FaktorAnak[] => {
  const c = (val: string, keys: string[]) => keys.some((k) => val.includes(k))

  return [
    {
      faktor: 'Umur',
      risiko: [
        { title: 'Kurang dari 3 tahun', skor: 4, selected: c(data.usia, ['Kurang dari 3 tahun']) },
        { title: '3-7 tahun', skor: 3, selected: c(data.usia, ['3-7 tahun', '3 - 7 tahun']) },
        { title: '7 - 13 tahun', skor: 2, selected: c(data.usia, ['7-13 tahun', '7 - 13 tahun']) },
        { title: 'Lebih dari 13 tahun', skor: 1, selected: c(data.usia, ['Lebih dari 13 tahun']) },
      ],
    },
    {
      faktor: 'Jenis Kelamin',
      risiko: [
        { title: 'Laki-laki', skor: 2, selected: c(data.jenis_kelamin, ['Laki-laki', 'Laki']) },
        { title: 'Perempuan', skor: 1, selected: c(data.jenis_kelamin, ['Perempuan']) },
      ],
    },
    {
      faktor: 'Diagnosa',
      risiko: [
        { title: 'Neurologi', skor: 4, selected: c(data.diagnosis, ['Neurologi']) },
        {
          title: 'Gangguan oksigenasi, respirator, dehidrasi, anemia, anoreksia, sinkop',
          skor: 3,
          selected: c(data.diagnosis, ['oksigenasi', 'respirator', 'dehidrasi', 'anemia']),
        },
        { title: 'Gangguan perilaku', skor: 2, selected: c(data.diagnosis, ['perilaku']) },
        { title: 'Penyakit lain', skor: 1, selected: c(data.diagnosis, ['Penyakit lain']) },
      ],
    },
    {
      faktor: 'Gangguan Kognitif',
      risiko: [
        { title: 'Keterbatasan daya pikir', skor: 3, selected: c(data.gangguan_kognitif, ['daya pikir']) },
        {
          title: 'Pelupa, berkurang orientasi sekitar',
          skor: 2,
          selected: c(data.gangguan_kognitif, ['Pelupa']),
        },
        {
          title: 'Kemampuan kognitif / orientasi baik',
          skor: 1,
          selected: c(data.gangguan_kognitif, ['orientasi baik']),
        },
      ],
    },
    {
      faktor: 'Faktor Lingkungan',
      risiko: [
        {
          title: 'Riwayat jatuh atau bayi / balita yang ditempatkan di tempat tidur (box)',
          skor: 4,
          selected: c(data.faktor_lingkungan, ['Riwayat jatuh', 'box']),
        },
        {
          title: 'Menggunakan alat bantu (ayunan, tempat tidur lipat)',
          skor: 3,
          selected: c(data.faktor_lingkungan, ['alat bantu']),
        },
        {
          title: 'Pasien berada pada tempat tidur standar',
          skor: 2,
          selected: c(data.faktor_lingkungan, ['tempat tidur standar']),
        },
        {
          title: 'Berada di area pasien rawat jalan',
          skor: 1,
          selected: c(data.faktor_lingkungan, ['rawat jalan']),
        },
      ],
    },
    {
      faktor: 'Respon terhadap pembedahan, sedasi dan anestesi',
      risiko: [
        { title: 'Dalam 24 jam', skor: 3, selected: c(data.respon, ['24 jam']) },
        { title: '> 48 jam / tanpa respon', skor: 2, selected: c(data.respon, ['48 jam']) },
        { title: 'Dalam 48 jam', skor: 1, selected: c(data.respon, ['48 Jam']) },
      ],
    },
    {
      faktor: 'Penggunaan Obat-obatan',
      risiko: [
        {
          title:
            'Menggunakan obat lebih dari 2 jenis: Sedatif, Barbiturat, Antidepresan, Diuretik, Narkotik',
          skor: 3,
          selected: c(data.penggunaan_obat, ['Bermacam-macam']),
        },
        {
          title: 'Menggunakan obat-obat lain / Tanpa obat',
          skor: 2,
          selected: c(data.penggunaan_obat, ['Salah satu']),
        },
        {
          title: 'Menggunakan 1 jenis obat dari daftar di atas',
          skor: 1,
          selected: c(data.penggunaan_obat, ['Pengobatan lain']),
        },
      ],
    },
  ]
}

const ReportPengkajianUlangResikoJatuhAnak = ({
  isReport,
  noreg,
  kdBagian,
}: ReportPengkajianUlangResikoJatuhAnakProps) => {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.reAsesmenResikoJatuhAnak, noreg],
    queryFn: () =>
      getAllReAsesmenResikoJatuhAnak({ noReg: noreg!, kdBagian: kdBagian! }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const Default = () => {
    const d = res[index]
    const faktor = buildFaktor(d)

    return (
      <LayoutBorderNo isReport={isReport} no='RM RI 38' rev='01.2020'>
        <div className='p-2 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-2'>
              PENGKAJIAN ULANG RISIKO JATUH PADA PASIEN ANAK
            </h3>
          </HeaderFormulir>

          <p className='text-justify text-black my-2'>
            Lakukan pengkajian (skoring) risiko jatuh pada saat terjadi perubahan
            kondisi pasien/therapi, saat pasien pindah ruangan lain, pasien risiko
            tinggi dikaji setiap 24 jam atau sesaat terjadi kasus jatuh.
          </p>

          <p className='text-black font-bold my-2 whitespace-pre-wrap'>
            {`SKOR : 7 - 11 Risiko Rendah (RR)\n       >= 12 Risiko Tinggi (RT)`}
          </p>

          {/* Header tabel */}
          <table className='w-full text-xs table-fixed border-collapse'>
            <colgroup>
              <col style={{ width: 40 }} />
              <col />
              <col />
              <col style={{ width: 70 }} />
            </colgroup>
            <thead>
              <tr className='font-bold text-center'>
                <th className='border border-black p-2'>No.</th>
                <th className='border border-black p-2'>FAKTOR RISIKO</th>
                <th className='border border-black p-2'>SKALA</th>
                <th className='border border-black p-2'>SKOR</th>
              </tr>
            </thead>
            <tbody>
              {faktor.map((f, fi) => (
                <Fragment key={fi}>
                  {f.risiko.map((r, ri) => (
                    <tr key={ri}>
                      {ri === 0 && (
                        <>
                          <td
                            rowSpan={f.risiko.length}
                            className='border border-black p-2 text-center align-middle'
                          >
                            {fi + 1}
                          </td>
                          <td
                            rowSpan={f.risiko.length}
                            className='border border-black p-2 align-middle font-semibold'
                          >
                            {f.faktor}
                          </td>
                        </>
                      )}
                      <td
                        className={cn(
                          'border border-black p-2',
                          r.selected && 'bg-green-200',
                        )}
                      >
                        {r.title}
                        {r.selected ? ' ✓' : ''}
                      </td>
                      <td className='border border-black p-2 text-center'>
                        {r.skor}
                      </td>
                    </tr>
                  ))}
                </Fragment>
              ))}
            </tbody>
            <tfoot>
              <tr className='font-bold'>
                <td colSpan={2} className='border border-black p-2 text-right'>
                  Total Skor
                </td>
                <td colSpan={2} className='border border-black p-2 text-center'>
                  {d.total}
                </td>
              </tr>
              <tr>
                <td
                  colSpan={2}
                  className='border border-black p-2 text-right font-bold'
                >
                  Lingkari Risiko Jatuh berdasarkan Skor
                </td>
                <td colSpan={2} className='border border-black p-2' />
              </tr>
              <tr>
                <td
                  colSpan={2}
                  className='border border-black p-2 text-right font-bold'
                >
                  Nama Perawat
                </td>
                <td colSpan={2} className='border border-black p-2 text-center'>
                  {d.nama_perawat}
                </td>
              </tr>
              <tr>
                <td
                  colSpan={2}
                  className='border border-black p-2 text-right font-bold'
                >
                  Paraf
                </td>
                <td colSpan={2} className='border border-black p-2' />
              </tr>
            </tfoot>
          </table>

          <p className='text-black mt-3 whitespace-pre-wrap'>
            {`Daftar obat berisiko :
Alkohol              Psikotropika              Benzodiazepine
Anti Kejang    Antihistamin              Hypoglicemic Agent
Diuretik           Sedative / Narkotika   Antihipertensi`}
          </p>

          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />
            <div className='flex items-end justify-center'>
              <div className='flex flex-col items-center text-center'>
                <p className='font-medium'>
                  Baturaja, {formatDateTime(d.insertDttm)} WIB
                </p>
                <p className='font-medium mb-4'>Perawat</p>
                <QRCode
                  value={d.nama_perawat ?? '-'}
                  className='w-[50px] h-[50px]'
                />
                <p className='mt-4'>
                  ({d.nama_perawat || '.........................'})
                </p>
              </div>
            </div>
          </div>
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {res != null &&
        res.length > 0 &&
        res.map((d, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {formatDateTime(d.insertDttm)}
          </Button>
        ))}

      {res.length > 0 && <Default />}
    </>
  )
}

export default ReportPengkajianUlangResikoJatuhAnak
