import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { RiwayatPengobatanModel } from '@/models/riwayat-pengobatan-model'
import { getRekonsiliasiObat } from '@/services/rekonsiliasi-obat'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

type RekonsiliasiObatProps = {
  noreg: string
  isReport?: boolean
}

const RekonsiliasiObat = ({ noreg, isReport }: RekonsiliasiObatProps) => {
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.rekonsiliasiObat, noreg],
    queryFn: () => getRekonsiliasiObat({ no_reg: noreg }),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 9a' rev='01.2020'>
      <div className='p-4 text-[10px]'>
        <HeaderFormulir
          nama={pasien?.nama_pasien ?? ''}
          tanggalLahir={pasien?.tgl_lahir ?? ''}
          noRm={pasien?.no_rm ?? ''}
          nik={pasien?.nik ?? ''}
        >
          <h3 className='text-[10px] font-bold text-center py-3'>
            FORMULIR REKONSILIASI OBAT
          </h3>
        </HeaderFormulir>

        {/* Table */}
        {/* Header */}
        <div className='flex mt-4'>
          <SimpleColumn name='No' className='text-[10px] flex-[0.2] ' />
          <SimpleColumn name='Nama Obat' className='text-[10px] flex-1' />
          <SimpleColumn
            name='Dosis dan Jumlah'
            className='text-[10px] flex-1 '
          />
          <SimpleColumn name='Frekuensi' className='text-[10px] flex-1' />
          <SimpleColumn name='Cara Pemberian' className='text-[10px] flex-1' />
          <SimpleColumn
            name='Waktu Pemberian Terakhir'
            className='text-[10px] flex-1'
          />
          <SimpleColumn name='Keterangan' className='text-[10px] flex-1' />
          <SimpleColumn name='Tindak Lanjut' className='text-[10px] flex-1' />
          <SimpleColumn
            name='Perubahan Aturan pakai'
            className='text-[10px] flex-1'
          />
          <SimpleColumn isLast name='PPA' className='text-[10px] flex-1' />
        </div>
        {/* Header */}
        {/* Body */}
        {res.map((item: RiwayatPengobatanModel, index: number) => (
          <div key={index} className='flex'>
            <SimpleColumn
              name={`${index + 1}`}
              className='text-[10px] flex-[0.2]  border-t-0'
            />

            <SimpleColumn
              name={item.nama_obat}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.dosis}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.frekuensi}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.cara_pemberian}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.waktu}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.keterangan}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.tindak_lanjut}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              name={item.perubahan_aturan_pakai}
              className='text-left text-[10px] flex-1 border-t-0'
            />
            <SimpleColumn
              isLast
              hasQR
              name={item.nama_perawat ?? ''}
              className='text-left text-[10px] flex-1 border-t-0'
            />
          </div>
        ))}
        {/* Body */}
        {/* Table */}
      </div>
    </LayoutBorderNo>
  )
}

export default RekonsiliasiObat
