import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import { InformasiPasien } from '@/components/informasi-pasien'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { getEarlyWarningSystemMeows } from '@/services/rekam-medis'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'

import { TextTitle } from './text-title'

type KontrolPasienMeowsProps = {
  noreg: string
  kdBagian: string
  isReport?: boolean
}

const KontrolPasienMeows = ({
  noreg,
  kdBagian,
  isReport,
}: KontrolPasienMeowsProps) => {
  const { pasien } = usePasienStore((state) => state)

  const kd = kdBagian || pasien?.kd_bagian || ''

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.ewsMeows, noreg],
    queryFn: () => getEarlyWarningSystemMeows(noreg, kd),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : null
  const rows =
    res?.kontrol_pasien.filter((i) => i.Kategori == 'KEBIDANAN') ?? []
  const keterangan = res?.keterangan

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (rows.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan' />

  return (
    <LayoutBorderNo isReport={isReport} no='RM 3b' rev='04.2020'>
      <div className='p-2 text-xs'>
        <h1 className='text-center text-black font-semibold mb-1'>
          MODIFIED EARLY OBSTETRIC WARNING SCORE (MEOWS)
        </h1>
        {pasien != null && (
          <InformasiPasien
            nama={pasien.nama_pasien}
            noRM={pasien.no_rm}
            ruangan={pasien.bagian}
            tanggalLahir={pasien.tgl_lahir}
          />
        )}

        <TextTitle title='Data Pemantauan MEOWS' />
        <table className='w-full border border-black border-collapse mb-2'>
          <thead>
            <tr className='bg-gray-100'>
              <th className='border border-black px-1'>Waktu</th>
              <th className='border border-black px-1'>RR</th>
              <th className='border border-black px-1'>SpO2</th>
              <th className='border border-black px-1'>O2</th>
              <th className='border border-black px-1'>Suhu</th>
              <th className='border border-black px-1'>TD Sistolik</th>
              <th className='border border-black px-1'>Nadi</th>
              <th className='border border-black px-1'>Kesadaran</th>
              <th className='border border-black px-1'>Nyeri</th>
              <th className='border border-black px-1'>Discharge</th>
              <th className='border border-black px-1'>Protein</th>
              <th className='border border-black px-1'>Skor MEOWS</th>
              <th className='border border-black px-1'>Ket.</th>
            </tr>
          </thead>
          <tbody>
            {rows.map((item, i) => (
              <tr key={i}>
                <td className='border border-black px-1'>{item.Waktu}</td>
                <td className='border border-black px-1 text-center'>
                  {item.Pernapasan}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Spo2}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Obsigen}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Suhu}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.TDSistolik}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.Nadi}
                </td>
                <td className='border border-black px-1'>{item.Kesadaran}</td>
                <td className='border border-black px-1'>{item.Nyeri}</td>
                <td className='border border-black px-1'>
                  {item.DischargeLochia}
                </td>
                <td className='border border-black px-1 text-center'>
                  {item.ProteinUrine}
                </td>
                <td className='border border-black px-1 text-center font-semibold'>
                  {item.SkorMEOWS}
                </td>
                <td className='border border-black px-1'>
                  {item.KeteranganMEOWS}
                </td>
              </tr>
            ))}
          </tbody>
        </table>

        {keterangan != null && (
          <>
            <TextTitle title='Keterangan' />
            <ul className='list-disc list-inside mb-2'>
              {keterangan.ringan != null && (
                <li>Ringan: {keterangan.ringan}</li>
              )}
              {keterangan.sedang != null && (
                <li>Sedang: {keterangan.sedang}</li>
              )}
              {keterangan.tinggi != null && (
                <li>Tinggi: {keterangan.tinggi}</li>
              )}
              {keterangan.henti_nafas != null && (
                <li>Henti Nafas: {keterangan.henti_nafas}</li>
              )}
            </ul>
          </>
        )}
      </div>
    </LayoutBorderNo>
  )
}

export default KontrolPasienMeows
