import { useState } from 'react'
import QRCode from 'react-qr-code'

import { useQuery } from '@tanstack/react-query'

import EmptyPlaceholder from '@/components/empty-placeholder'
import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { Button } from '@/components/ui/button'
import { getAllAsesmenFisioterapi } from '@/services/asesmen-fisioterapi'
import { usePasienStore } from '@/store/pasien.store'
import { constants } from '@/utils/constants'
import { formatDateTime } from '@/utils/formatDate'

import { TextField } from './text-field'

interface ReportAsesmenFisioterapiProps {
  isReport?: boolean
  noreg?: string
  no?: string
  kdBagian?: string
}

const ReportAsesmenFisioterapi = ({
  isReport,
  noreg,
  kdBagian,
}: ReportAsesmenFisioterapiProps) => {
  const [index, setIndex] = useState(0)
  const { pasien } = usePasienStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.rekamMedis.asesmenFisioterapi, noreg],
    queryFn: () => getAllAsesmenFisioterapi(noreg!, kdBagian!),
    enabled: !!noreg,
  })

  const res = data != null ? data.response : []

  if (isLoading) return <Loading />
  if (isError) return <Error />
  if (res == null || res.length == 0)
    return <EmptyPlaceholder message='Data tidak ditemukan.' />

  const Default = () => {
    return (
      <LayoutBorderNo isReport={isReport} no='RM 4i' rev='01.2020'>
        <div className='p-4 text-xs'>
          <HeaderFormulir
            nama={pasien?.nama_pasien ?? ''}
            tanggalLahir={pasien?.tgl_lahir ?? ''}
            noRm={pasien?.no_rm ?? ''}
            nik={pasien?.nik ?? ''}
          >
            <h3 className='text-xs font-bold text-center py-3'>
              PENGKAJIAN FISIOTERAPI
            </h3>
          </HeaderFormulir>

          <div className='flex p-2'>
            <p className='text-xs text-black'>
              Tanggal Pengkajian : {formatDateTime(res[index].insert_dttm)} WIB
            </p>
          </div>

          <div className='gap-4 border border-black p-1 mb-1'>
            <div className='mb-4'>
              <h3 className='text-black font-medium mt-4'>Diagnosa Medis</h3>
              <TextField title='Diagnosa' value={res[index].diagnosa_medis} />

              <h3 className='text-black font-medium mt-4'>Observasi</h3>
              <TextField title='Anamnese' value={res[index].anamnese} />
              <TextField title='Awal Gerakan' value={res[index].awal_gerakan} />
              <TextField title='Keseimbangan' value={res[index].keseimbangan} />
              <TextField
                title='Gerakan Kompensasi'
                value={res[index].gerakan_kompensasi}
              />

              <h3 className='text-black font-medium mt-4'>Pemeriksaan Fisik</h3>
              <TextField title='Tonus Otot' value={res[index].tonus_otot} />
              <TextField
                title='Respon dan Sensasi'
                value={res[index].response_dan_sensasi}
              />
              <TextField
                title='Reaksi saat gerakan'
                value={res[index].reaksi_saat_gerakan}
              />

              <h3 className='text-black font-medium mt-4'>
                Program Fisioterapi
              </h3>
              <TextField
                title='Program Fisioterapi'
                value={res[index].program_fisioterapi}
              />

              <h3 className='text-black font-medium mt-4'>
                Penatalaksanaan Intervensi Yang Telah Dilakukan
              </h3>
              <TextField title='Evaluasi' value={res[index].evaluasi} />
            </div>
          </div>

          {/* Tanda Tangan */}
          <div className='ml-4'>
            <div className='py-10' />
            <div className='flex items-end justify-between'>
              <div className='w-full text-center flex flex-col justify-between items-center gap-4'>
                <p className='font-medium'>Fisioterapis</p>
                {res[index].user ? (
                  <>
                    <QRCode
                      value={res[index].user}
                      className='h-[50px] w-[50px]'
                    />
                    <p>( {res[index].user} )</p>
                  </>
                ) : (
                  <div className='h-[50px]' />
                )}
              </div>
            </div>
          </div>
          {/* Tanda Tangan */}
        </div>
      </LayoutBorderNo>
    )
  }

  return (
    <>
      {res != null &&
        res.length > 0 &&
        res.map((_, idx) => (
          <Button
            className='ml-2 my-2'
            variant={idx == index ? 'default' : 'outline'}
            key={idx}
            onClick={() => {
              setIndex(idx)
            }}
          >
            {idx + 1}
          </Button>
        ))}

      {res.length > 0 && <Default />}
    </>
  )
}

export default ReportAsesmenFisioterapi
