import { z } from 'zod'

import { useForm } from 'react-hook-form'

import { zodResolver } from '@hookform/resolvers/zod'
import { useMutation, useQueryClient } from '@tanstack/react-query'

import { createTriaseNew, updateTriaseNew } from '@/services/triase'
import { useGlobalStore } from '@/store/global.store'
import { constants } from '@/utils/constants'

const triaseNewSchema = z.object({
  nama_pasien: z.string(),
  tanggal_lahir: z.string(),
  tanggal_jam: z.string(),
  alamat: z.string(),
  nama_perawat: z.string(),
  nama_dokter: z.string(),
  transportasi: z.string(),
  cara_masuk: z.string(),
  informasi_dari: z.string(),
  alasan_masuk: z.string(),
  trauma: z.string().optional().default(''),
  non_trauma: z.string().optional().default(''),
  penyebab_cedera: z.string().optional().default(''),
  keluhan_utama: z.string(),
  kondisi_pasien: z.string(),
  respirasi: z.string(),
  nadi: z.string(),
  oksigen: z.string(),
  td: z.string(),
  bb: z.string(),
  tb: z.string(),
  suhu: z.string(),
  pupil_kiri: z.string(),
  pupil_kanan: z.string(),
  reflek_cahaya_kiri: z.string(),
  reflek_cahaya_kanan: z.string(),
  gcs_e: z.string(),
  gcs_m: z.string(),
  gcs_v: z.string(),
  skala_triase: z.string(),
  jalan_nafas: z.string(),
  pernafasan: z.string(),
  pernafasan_neonatus: z.string().optional().default(''),
  sirkulasi: z.string(),
  sirkulasi_neonatus: z.string().optional().default(''),
  gcs: z.string(),
  nyeri: z.string(),
  kondisi_mental: z.string(),
  resiko_penularan_infeksi: z.string(),
  no_bed: z.string().optional().default(''),
  riwayat_penyakit_sekarang: z.string().optional().default(''),
  tindak_lanjut: z.string(),
  jam_periksa: z.string(),
  triase_checklist: z.string().optional(),
})

export type CreateTriaseNewReq = z.infer<typeof triaseNewSchema>

export function useTriaseNew(
  editId?: number,
  initialData?: CreateTriaseNewReq,
) {
  const queryClient = useQueryClient()
  const { setDialogId, setShowDialog } = useGlobalStore()

  const form = useForm<CreateTriaseNewReq>({
    resolver: zodResolver(triaseNewSchema),
    defaultValues: initialData || {
      nama_pasien: '',
      tanggal_lahir: '',
      tanggal_jam: '',
      alamat: '',
      nama_perawat: '',
      nama_dokter: '',
      transportasi: '',
      cara_masuk: '',
      informasi_dari: '',
      alasan_masuk: '',
      penyebab_cedera: '',
      keluhan_utama: '',
      kondisi_pasien: '',
      respirasi: '',
      nadi: '',
      oksigen: '',
      td: '',
      bb: '',
      tb: '',
      suhu: '',
      pupil_kiri: '',
      pupil_kanan: '',
      reflek_cahaya_kiri: '',
      reflek_cahaya_kanan: '',
      gcs_e: '',
      gcs_m: '',
      gcs_v: '',
      skala_triase: '',
      jalan_nafas: '',
      pernafasan: '',
      pernafasan_neonatus: '',
      sirkulasi: '',
      sirkulasi_neonatus: '',
      gcs: '',
      nyeri: '',
      kondisi_mental: '',
      resiko_penularan_infeksi: '',
      no_bed: '',
      riwayat_penyakit_sekarang: '',
      tindak_lanjut: '',
      jam_periksa: '',
    },
  })

  const { mutateAsync, isPending } = useMutation({
    mutationFn: editId ? updateTriaseNew : createTriaseNew,
  })

  async function onSubmit(values: CreateTriaseNewReq) {
    try {
      if (editId) {
        await mutateAsync({ id: editId, data: values })
      } else {
        await mutateAsync({ data: values })
      }
      await queryClient.invalidateQueries({
        queryKey: [constants.queryKey.triaseNew.list],
      })
      form.reset()
      setDialogId('')
      setShowDialog(false)
    } catch (error) {
      console.error('Failed to save triase new:', error)
    }
  }

  return { form, onSubmit, isPending }
}
