import dayjs from 'dayjs'

const month: Record<string, string> = {
  Jan: 'Januari',
  Feb: 'Februari',
  Mar: 'Maret',
  Apr: 'April',
  May: 'Mei',
  Jun: 'Juni',
  Jul: 'Juli',
  Aug: 'Agustus',
  Sep: 'September',
  Oct: 'Oktober',
  Nov: 'November',
  Dec: 'Desember',
}

export function formatDate(date: string) {
  if (date == '') return ''

  const formatted = dayjs(date).format('DD MMM YYYY')
  if (formatted == 'Invalid Date') return ''

  const d = formatted.split(' ')[0]
  const m = formatted.split(' ')[1]
  const y = formatted.split(' ')[2]

  const formatId = `${d} ${month[m]} ${y}`
  return formatId
}

export function formatDatev2(date: string) {
  const formatted = dayjs(date).format('DD/MM')

  return formatted
}

export function formatDateTimev2(date: string) {
  if (date == '') return ''
  const formatted = dayjs(date).format('HH:mm')

  return formatted
}

export function formatDateTime(date: string) {
  const formatted = dayjs(date).format('DD/MMM/YYYY HH:mm')

  const d = formatted.split('/')[0]
  const m = formatted.split('/')[1]
  const y = formatted.split('/')[2]

  const formatId = `${d} ${month[m]} ${y}`
  return formatId
}

