import { useQuery } from '@tanstack/react-query'

import Error from '@/components/error'
import HeaderFormulir from '@/components/header-formulir'
import { LayoutBorderNo } from '@/components/layout-border-no'
import Loading from '@/components/loading'
import { SimpleColumn } from '@/components/simple-column'
import { getReportCpptByNoreg } from '@/services/cppt'
import { useAuthStore } from '@/store/auth.store'
// import { useGlobalStore } from '@/store/global.store'
import { usePasienStore } from '@/store/pasien.store'
import { CpptByNoreg } from '@/type'
import { constants } from '@/utils/constants'

// import { Edit } from 'lucide-react'

interface CPPTResumeProps {
  isReport?: boolean
  noreg?: string
  no?: string
}

export function CPPTResume({ isReport = false, noreg = '' }: CPPTResumeProps) {
  // const { setDialogId, setShowDialog, setItem } = useGlobalStore(
  //   (state) => state
  // )
  const { pasien } = usePasienStore((state) => state)
  const { user } = useAuthStore((state) => state)

  const { data, isLoading, isError } = useQuery({
    queryKey: [constants.queryKey.pasien.cppt.report, noreg],
    queryFn: () => getReportCpptByNoreg(noreg),
  })

  const result = data?.response != null ? data?.response : ({} as CpptByNoreg)

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <LayoutBorderNo no='RM 7' rev='04.2020' isReport={isReport}>
      {/* Content */}
      <div className='p-2'>
        <HeaderFormulir
          nama={pasien!.nama_pasien}
          tanggalLahir={pasien!.tgl_lahir}
          noRm={pasien!.no_rm}
          nik={pasien!.nik}
        >
          <h3>CATATAN PERKEMBANGAN PASIEN</h3>
          <h3>TERINTEGRASI</h3>
        </HeaderFormulir>
        <div>
          {/* Header */}
          <div className='flex text-xs'>
            <SimpleColumn head name='Tanggal & Jam' className='w-[100px]' />
            <SimpleColumn
              head
              name='Professional Pemberi Asuhan'
              className='flex-[0.5]'
            />
            <SimpleColumn head name='Hasil Pengkajian' className='flex-1' />
            <SimpleColumn head name='Instruksi PPA' className='flex-[0.5]' />
            <SimpleColumn
              head
              name='Verifikasi DPJP'
              isLast={isReport || pasien?.bagian !== user?.bagian}
              className='flex-[0.5]'
            />
            {!isReport && pasien?.bagian === user?.bagian && (
              <SimpleColumn head name='Action' isLast className='w-[100px]' />
            )}
          </div>
          {/* Header */}

          {/* Body */}

          {result.cppt.length > 0 &&
            result.cppt.map((item) => (
              <div className='flex text-xs' key={item.id}>
                <SimpleColumn name={item.tanggal} className='w-[100px]' />
                <SimpleColumn
                  isChild={
                    <>
                      <p className='text-xs font-semibold'>
                        <span className='hide-when-print'>
                          {item.insert_user_id} -{' '}
                        </span>
                        {item.pemberi_asuhan}
                      </p>
                    </>
                  }
                  className='flex-[0.5]'
                />
                <SimpleColumn
                  isChild={
                    <>
                      {item.cppt.situation != '' ? (
                        <>
                          <Item k='S' value={item.cppt.situation} />
                          <Item k='B' value={item.cppt.background} />
                          <Item k='A' value={item.cppt.asesmen} />
                          <Item k='R' value={item.cppt.recommendation} />
                        </>
                      ) : item.kelompok == 'Ahli Gizi' ? (
                        <>
                          {' '}
                          <Item k='A' value={item.adime.asesmen} />
                          <Item k='D' value={item.adime.diagnosa} />
                          <Item k='I' value={item.adime.intervensi} />
                          <Item
                            k='ME'
                            value={item.adime.monitor_evaluasi}
                          />{' '}
                        </>
                      ) : (
                        <>
                          <Item k='S' value={item.cppt.subjektif} />
                          <Item k='O' value={item.cppt.objektif} />
                          <Item k='A' value={item.cppt.asesmen} />
                          <Item k='P' value={item.cppt.plan} />
                        </>
                      )}
                    </>
                  }
                  className='justify-start items-start flex-1'
                  className2='text-left'
                />
                <SimpleColumn
                  name={item.instruksi_ppa}
                  className='flex-[0.5]'
                />
                <SimpleColumn
                  name={item.dpjp}
                  // name={
                  //   item.kelompok == 'Dokter'
                  //     ? item.pemberi_asuhan
                  //     : item.cppt.verifikasi_ttd != ''
                  //       ? item.dpjp
                  //       : ''
                  // }
                  hasQR
                  isLast={isReport || pasien?.bagian !== user?.bagian}
                  className='flex-[0.5]'
                />
                {/* {!isReport && pasien?.bagian === user?.bagian && (
                  <SimpleColumn
                    isChild={
                      <Edit
                        className='hover:cursor-pointer'
                        onClick={() => {
                          setShowDialog(true)
                          console.log('selected cppt item', item)
                          setItem(item)
                          if (item.cppt.includes('Subjektif')) {
                            setDialogId('dialog-update-cppt-soap')
                          } else {
                            setDialogId('dialog-update-cppt-sbar')
                          }
                        }}
                      />
                    }
                    isLast
                    className='w-[100px]'
                  />
                )} */}
              </div>
            ))}
          {/* Body */}
        </div>
      </div>
      {/* Content */}
    </LayoutBorderNo>
  )
}

const Item = ({ k, value }: { k: string; value: string }) => {
  return (
    <span className='flex flex-shrink-0 gap-1'>
      <strong>{k}</strong> :{' '}
      <p className='text-xs text-black text-left'>{value}</p>
    </span>
  )
}
