import {
  DokterModel,
  PerawatModel,
  ResponseTriaseNew,
} from '@/models/triase-new'
import type { Response, Triase } from '@/type'

import { get, post } from './api'

const getTriase = async ({
  noreg,
}: {
  noreg: string
}): Promise<Response<Triase>> => {
  const response = await get(`/v1/report-triase/${noreg}`)

  return response.data
}

const getAllDokter = async (): Promise<Response<DokterModel[]>> => {
  const response = await get(`/v1/triase-new/get-dokter`, {})

  return response.data
}

const getAllPerawat = async (): Promise<Response<PerawatModel[]>> => {
  const response = await get(`/v1/triase-new/get-perawat`, {})

  return response.data
}

const getTriaseNew = async (): Promise<Response<ResponseTriaseNew[]>> => {
  const response = await post(`/v1/triase-new/all`, {})

  return response.data
}

const searchTriaseNew = async ({
  page,
  limit,
  search,
  date_from,
  date_to,
}: {
  page: number
  limit: number
  search: string
  date_from?: string
  date_to?: string
}): Promise<Response<ResponseTriaseNew[]>> => {
  const response = await post(`/v1/triase-new/search`, {
    page,
    limit,
    search,
    date_from,
    date_to,
  })

  return response.data
}

const createTriaseNew = async ({
  data,
}: {
  data: any
}): Promise<Response<unknown>> => {
  const response = await post(`/v1/triase-new/save`, { data: data })

  return response.data
}

const updateTriaseNew = async ({
  id,
  data,
}: {
  id?: number
  data: any
}): Promise<Response<unknown>> => {
  const response = await post(`/v1/triase-new/update`, { id, data })

  return response.data
}

const deleteTriaseNew = async ({
  id,
}: {
  id: number
}): Promise<Response<unknown>> => {
  const response = await post(`/v1/triase-new/delete`, { id: id })

  return response.data
}

export {
  getTriase,
  getTriaseNew,
  createTriaseNew,
  updateTriaseNew,
  deleteTriaseNew,
  getAllDokter,
  getAllPerawat,
  searchTriaseNew,
}
