import { cn } from '@/lib/utils'
import type { AsuhanKeperawatan } from '@/models/asesmen-keperawatan-igd'
import { Asuhan } from '@/models/asesmen-keperawatan-rawat-inap'
import { formatDate } from '@/utils/formatDate'

type AsuhanKeperawatanProps = {
  data: Asuhan[] | AsuhanKeperawatan[]
}

const AsuhanKeperawatan = ({ data }: AsuhanKeperawatanProps) => {
  if (data.length == 0) return

  return data.map((item) => (
    <div key={item.tanggal}>
      <div className='bg-gray-200 p-1 border border-x-0 border-t-0 border-black'>
        <p className='text-black font-semibold'>
          {item.diagnosa.judul} <br /> {formatDate(item.tanggal)}
        </p>
      </div>
      {item.deskripsi_slki.map((slki, idx) => (
        <div
          key={slki.no_urut}
          className={cn(
            'border border-black border-x-0 border-t-0 mb-1 py-1',
            idx == item.deskripsi_slki.length - 1 && 'mb-0 border-b-0',
          )}
        >
          <p className='mx-1'>{slki.nama_sllki}</p>
        </div>
      ))}
      <div className='bg-gray-200 p-1 border border-x-0 border-black'>
        <p className='text-black font-semibold'>Implementasi</p>
      </div>
      {item.implementasi.map((i, idx) => (
        <div
          key={i.id}
          className={cn(
            'border border-black border-x-0 border-t-0 mb-1 py-1',
            idx == item.implementasi.length - 1 && 'mb-0 border-b-0',
          )}
        >
          <p className='mx-1'>{i.deskripsi}</p>
        </div>
      ))}
    </div>
  ))
}

export default AsuhanKeperawatan
