import { format } from 'date-fns'
import { id } from 'date-fns/locale'
import { Calendar as CalendarIcon, Loader2, PlusSquareIcon } from 'lucide-react'

import { useEffect, useState } from 'react'

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { createFileRoute } from '@tanstack/react-router'

import Error from '@/components/error'
import Loading from '@/components/loading'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Button } from '@/components/ui/button'
import { Calendar } from '@/components/ui/calendar'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogTitle,
} from '@/components/ui/dialog'
import { Input } from '@/components/ui/input'
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from '@/components/ui/popover'
import { columns } from '@/features/triase/components/table/columns'
import { DataTable } from '@/features/triase/components/table/data-table'
import { TriaseNewForm } from '@/features/triase/components/triase-new-form'
import { TriaseNewDetail } from '@/features/triase/components/triase-new-report'
import { ResponseTriaseNew } from '@/models/triase-new'
import { deleteTriaseNew, searchTriaseNew } from '@/services/triase'
import { useGlobalStore } from '@/store/global.store'
import { MetaPaginated } from '@/type'
import { constants } from '@/utils/constants'

const LIMIT = 10

export const Route = createFileRoute('/triase-page')({
  component: TriasePage,
})

export default function TriasePage() {
  const isLogin = JSON.parse(sessionStorage.getItem('isLogin')!)

  if (!isLogin) {
    // if not logged in, navigate to login page
    window.location.replace('/login')
  }

  const { dialogId, setDialogId, showDialog, setShowDialog, item } =
    useGlobalStore((s) => s)

  const queryClient = useQueryClient()

  const [search, setSearch] = useState('')
  const [debouncedSearch, setDebouncedSearch] = useState('')
  const [page, setPage] = useState(1)
  const [dateFrom, setDateFrom] = useState('')
  const [dateTo, setDateTo] = useState('')
  const [debouncedDateFrom, setDebouncedDateFrom] = useState('')
  const [debouncedDateTo, setDebouncedDateTo] = useState('')

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedSearch(search)
      setPage(1)
    }, 400)
    return () => clearTimeout(timer)
  }, [search])

  useEffect(() => {
    const timer = setTimeout(() => {
      setDebouncedDateFrom(dateFrom)
      setDebouncedDateTo(dateTo)
      setPage(1)
    }, 400)
    return () => clearTimeout(timer)
  }, [dateFrom, dateTo])

  const { data, isLoading, isError } = useQuery({
    queryKey: [
      constants.queryKey.triaseNew.list,
      page,
      debouncedSearch,
      debouncedDateFrom,
      debouncedDateTo,
    ],
    queryFn: () =>
      searchTriaseNew({
        page,
        limit: LIMIT,
        search: debouncedSearch,
        date_from: debouncedDateFrom || undefined,
        date_to: debouncedDateTo || undefined,
      }),
  })

  const { mutateAsync: mutateDelete, isPending: isDeleting } = useMutation({
    mutationFn: deleteTriaseNew,
  })

  const result = data?.response ?? []
  const meta = data?.metadata as MetaPaginated | undefined
  const totalPage = meta?.total_page ?? 1
  const selectedItem = item as ResponseTriaseNew | null

  if (isLoading) return <Loading />
  if (isError) return <Error />

  return (
    <>
      <div className='flex'>
        {/* Main Content */}
        <main className='h-[calc(100vh-5rem)] overflow-y-scroll w-full p-4 bg-gradient-to-b from-blue-500  to-[#0066CB] mt-2 mx-2 rounded-md'>
          <div className='my-4 flex items-start justify-between gap-3'>
            <Input
              placeholder='Cari nama pasien...'
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              className='max-w-sm bg-white text-black'
            />

            <div className='mb-3 flex gap-3'>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant='outline'
                    className='w-[200px] justify-start text-left font-normal'
                  >
                    <CalendarIcon className='mr-2 h-4 w-4' />
                    {dateFrom
                      ? format(new Date(dateFrom), 'PPP', { locale: id })
                      : 'Dari tanggal'}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className='w-auto p-0 bg-white' align='start'>
                  <Calendar
                    mode='single'
                    selected={dateFrom ? new Date(dateFrom) : undefined}
                    onSelect={(date) => {
                      if (date) {
                        setDateFrom(format(date, 'yyyy-MM-dd'))
                      }
                    }}
                    disabled={(date) =>
                      dateTo ? date > new Date(dateTo) : false
                    }
                  />
                </PopoverContent>
              </Popover>
              <Popover>
                <PopoverTrigger asChild>
                  <Button
                    variant='outline'
                    className='w-[200px] justify-start text-left font-normal'
                  >
                    <CalendarIcon className='mr-2 h-4 w-4' />
                    {dateTo
                      ? format(new Date(dateTo), 'PPP', { locale: id })
                      : 'Hingga tanggal'}
                  </Button>
                </PopoverTrigger>
                <PopoverContent className='w-auto p-0 bg-white' align='start'>
                  <Calendar
                    mode='single'
                    selected={dateTo ? new Date(dateTo) : undefined}
                    onSelect={(date) => {
                      if (date) {
                        setDateTo(format(date, 'yyyy-MM-dd'))
                      }
                    }}
                    disabled={(date) =>
                      dateFrom ? date < new Date(dateFrom) : false
                    }
                  />
                </PopoverContent>
              </Popover>

              <Button
                onClick={() => {
                  setDialogId('dialog-add-triase-new')
                  setShowDialog(true)
                }}
                className='bg-white text-blue-500 hover:bg-gray-100 hover:text-blue-700'
              >
                Tambah <PlusSquareIcon />
              </Button>
            </div>
          </div>

          <DataTable columns={columns} data={result} />
          <div className='flex items-center justify-between mt-3'>
            <p className='text-white text-sm'>
              Halaman {page} dari {totalPage}
            </p>
            <div className='flex gap-2'>
              <Button
                variant='outline'
                size='sm'
                disabled={page <= 1}
                onClick={() => setPage((p) => p - 1)}
                className='text-black'
              >
                &laquo; Sebelumnya
              </Button>
              <Button
                variant='outline'
                size='sm'
                disabled={page >= totalPage}
                onClick={() => setPage((p) => p + 1)}
                className='text-black'
              >
                Selanjutnya &raquo;
              </Button>
            </div>
          </div>
        </main>
        {/* Main Content */}
      </div>

      <Dialog
        modal
        open={showDialog && dialogId == 'dialog-add-triase-new'}
        onOpenChange={() => {
          setShowDialog(!showDialog)
        }}
      >
        <DialogTitle className='sr-only'>Tambah Triase Baru</DialogTitle>
        <DialogDescription className='sr-only'>
          Form tambah data triase pasien yang belum terdaftar
        </DialogDescription>
        <DialogContent className='max-w-2xl sm:max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Tambah Triase Baru
          </h2>
          <TriaseNewForm />
        </DialogContent>
      </Dialog>

      <Dialog
        modal
        open={dialogId == 'dialog-detail-triase-new'}
        onOpenChange={() => setDialogId('')}
      >
        <DialogTitle className='sr-only'>Detail Triase</DialogTitle>
        <DialogDescription className='sr-only'>
          Detail data triase pasien
        </DialogDescription>
        <DialogContent className='max-w-4xl max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Detail Triase — {selectedItem?.data.nama_pasien}
          </h2>
          {selectedItem != null && (
            <TriaseNewDetail
              item={selectedItem}
              onEdit={() => {
                setDialogId('dialog-edit-triase-new')
              }}
            />
          )}
        </DialogContent>
      </Dialog>

      <Dialog
        modal
        open={dialogId == 'dialog-edit-triase-new'}
        onOpenChange={() => {
          setDialogId('dialog-detail-triase-new')
        }}
      >
        <DialogTitle className='sr-only'>Edit Triase</DialogTitle>
        <DialogDescription className='sr-only'>
          Form edit data triase pasien
        </DialogDescription>
        <DialogContent className='max-w-2xl sm:max-h-[90vh] overflow-y-auto'>
          <h2 className='text-xl font-semibold text-blue-600 pt-2'>
            Edit Triase — {selectedItem?.data.nama_pasien}
          </h2>
          {selectedItem != null && (
            <TriaseNewForm
              editId={selectedItem.id}
              initialData={selectedItem.data}
            />
          )}
        </DialogContent>
      </Dialog>

      <AlertDialog open={dialogId == 'dialog-delete-triase-new'}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus data triase?</AlertDialogTitle>
            <AlertDialogDescription>
              Tindakan ini tidak dapat dibatalkan. Data triase atas nama{' '}
              <span className='font-semibold'>
                {selectedItem?.data.nama_pasien ?? ''}
              </span>{' '}
              akan dihapus secara permanen.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel
              disabled={isDeleting}
              onClick={() => {
                setDialogId('')
              }}
            >
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              className='bg-red-500 hover:bg-red-600'
              disabled={isDeleting}
              onClick={async () => {
                if (!selectedItem) return
                await mutateDelete({ id: selectedItem.id })
                await queryClient.invalidateQueries({
                  queryKey: [constants.queryKey.triaseNew.list],
                })
                setDialogId('')
              }}
            >
              {isDeleting ? (
                <>
                  <Loader2 className='mr-2 h-4 w-4 animate-spin' />
                  Menghapus...
                </>
              ) : (
                'Hapus'
              )}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}
