import type {
  RegisterPasien,
  ReportGeneralConsent,
  ReportGeneralConsentRanap,
  Response,
} from '@/type'

import { get, post } from './api'
import { post as p } from './api-2'

const getGeneralConsent = async (
  no_reg: string,
  bagian: string,
): Promise<Response<ReportGeneralConsent>> => {
  const response = await get(`/v1/general-consent/${no_reg}/${bagian}`)

  return response.data
}

const getGeneralConsentReport = async (
  no_rm: string,
  noreg: string,
  pelayanan: string,
): Promise<Response<ReportGeneralConsentRanap>> => {
  const response = await p(`/v1/general-consent-report`, {
    noreg: noreg,
    no_rm: no_rm,
    pelayanan: pelayanan,
  })

  return response.data
}

const getRegisterPasien = async ({
  no_rm,
  kd_bagian,
}: {
  no_rm: string
  kd_bagian?: string
}): Promise<Response<RegisterPasien[]>> => {
  const response = await post(`/v1/register-pasien`, { no_rm, kd_bagian })

  return response.data
}

export { getGeneralConsent, getRegisterPasien, getGeneralConsentReport }
