function Row({ label, value }: { label: string; value?: string }) {
  return (
    <div className='flex gap-2 py-1 border-b border-gray-100 last:border-0'>
      <span className='min-w-[200px] text-sm text-gray-500'>{label}</span>
      <span className='text-sm font-medium text-gray-800 flex-1'>
        {value || '-'}
      </span>
    </div>
  )
}

function Section({
  title,
  children,
}: {
  title: string
  children: React.ReactNode
}) {
  return (
    <div className='mb-5'>
      <h3 className='text-sm font-semibold text-blue-600 border-b border-blue-200 pb-1 mb-2'>
        {title}
      </h3>
      {children}
    </div>
  )
}

type ChecklistRow = {
  label: string
  fieldKey: ChecklistFieldKey
  isNeonatus?: boolean
  p1: string[]
  p2: string[]
  p3: string[]
  p4: string[]
}

function parseTriaseChecklist(
  value?: TriaseChecklist | string,
): TriaseChecklist | undefined {
  if (!value) return undefined
  if (typeof value === 'string') {
    try {
      return JSON.parse(value) as TriaseChecklist
    } catch {
      return undefined
    }
  }

  return value
}

