export function TriaseNewDetail({
  item,
  onEdit,
}: {
  item: ResponseTriaseNew
  onEdit?: () => void
}) {
  const d = item.data
  const checklist = parseTriaseChecklist(d.triase_checklist)

  const isChecked = (
    fieldKey: ChecklistFieldKey,
    priority: PriorityKey,
    value: string,
  ) => checklist?.[fieldKey]?.[priority]?.includes(value) ?? false

  return (
    <div className='space-y-1'>
      {onEdit && (
        <div className='mb-4 flex justify-end'>
          <Button
            onClick={onEdit}
            className='bg-blue-500 hover:bg-blue-600 text-white'
          >
            <Edit className='mr-2 h-4 w-4' />
            Edit
          </Button>
        </div>
      )}
      <Section title='Data Pasien'>
        <Row label='Nama Pasien' value={d.nama_pasien} />
        <Row label='Tanggal Lahir' value={d.tanggal_lahir} />
        <Row label='Tanggal & Jam Masuk' value={d.tanggal_jam} />
        <Row label='Jam Periksa' value={d.jam_periksa} />
        <Row label='Alamat' value={d.alamat} />
        <Row label='No Bed' value={d.no_bed} />
      </Section>

      <Section title='Petugas'>
        <Row label='Nama Perawat' value={d.nama_perawat} />
        <Row label='Nama Dokter' value={d.nama_dokter} />
      </Section>

      <Section title='Anamnesis'>
        <Row label='Transportasi' value={d.transportasi} />
        <Row label='Cara Masuk' value={d.cara_masuk} />
        <Row label='Informasi Dari' value={d.informasi_dari} />
        <Row label='Alasan Masuk' value={d.alasan_masuk} />
        <Row label='Trauma' value={d.trauma} />
        <Row label='Non Trauma' value={d.non_trauma} />
        <Row label='Penyebab Cedera' value={d.penyebab_cedera} />
        <Row label='Keluhan Utama' value={d.keluhan_utama} />
        <Row
          label='Riwayat Penyakit Sekarang'
          value={d.riwayat_penyakit_sekarang}
        />
      </Section>

      <Section title='Kondisi & Tanda Vital'>
        <Row label='Kondisi Pasien' value={d.kondisi_pasien} />
        <Row label='Respirasi (/mnt)' value={d.respirasi} />
        <Row label='Nadi (/mnt)' value={d.nadi} />
        <Row label='SpO2 (%)' value={d.oksigen} />
        <Row label='Tekanan Darah' value={d.td} />
        <Row label='BB (kg)' value={d.bb} />
        <Row label='TB (cm)' value={d.tb} />
        <Row label='Suhu (°C)' value={d.suhu} />
      </Section>

      <Section title='Pupil'>
        <Row label='Pupil Kiri' value={d.pupil_kiri} />
        <Row label='Pupil Kanan' value={d.pupil_kanan} />
        <Row label='Reflek Cahaya Kiri' value={d.reflek_cahaya_kiri} />
        <Row label='Reflek Cahaya Kanan' value={d.reflek_cahaya_kanan} />
      </Section>

      <Section title='GCS'>
        <Row label='GCS E' value={d.gcs_e} />
        <Row label='GCS M' value={d.gcs_m} />
        <Row label='GCS V' value={d.gcs_v} />
        <Row label='Total GCS' value={d.gcs} />
      </Section>

      <Section title='Triase & Status Klinis'>
        <Row label='Skala Triase' value={d.skala_triase} />

        <Row label='Nyeri (0-10)' value={d.nyeri} />
        <Row label='Kondisi Mental' value={d.kondisi_mental} />
        <Row
          label='Risiko Penularan Infeksi'
          value={d.resiko_penularan_infeksi}
        />
        <Row label='Tindak Lanjut' value={d.tindak_lanjut} />
      </Section>

      <Section title='Pemeriksaan (Examination)'>
        <div className='overflow-x-auto'>
          <div className='min-w-[760px] border border-gray-200 rounded'>
            <div className='grid grid-cols-[200px_repeat(4,1fr)] bg-gray-50 text-xs font-semibold text-gray-600'>
              <div className='border-b border-gray-200 p-2'>Pemeriksaan</div>
              <div className='border-b border-gray-200 p-2 text-red-600'>
                Prioritas 1 (Area Resusitasi)
              </div>
              <div className='border-b border-gray-200 p-2 text-yellow-600'>
                Prioritas 2 (Area Tindakan)
              </div>
              <div className='border-b border-gray-200 p-2 text-green-600'>
                Prioritas 3 (Area Observasi)
              </div>
              <div className='border-b border-gray-200 p-2'>
                Death on Arrival (DOA)
              </div>
            </div>

            {triaseChecklistRows.map((row, index) => (
              <div
                key={`${row.label}-${index}`}
                className='grid grid-cols-[200px_repeat(4,1fr)] text-xs text-gray-700'
              >
                <div className='border-t border-gray-200 p-2'>
                  <p className='font-semibold text-gray-700'>{row.label}</p>
                  {row.isNeonatus && (
                    <p className='text-[11px] text-gray-500'>Neonatus</p>
                  )}
                </div>
                {(['p1', 'p2', 'p3', 'p4'] as PriorityKey[]).map((priority) => {
                  const items = row[priority]
                  const priorityColorMap = {
                    p1: 'text-red-600',
                    p2: 'text-yellow-600',
                    p3: 'text-green-600',
                    p4: 'text-gray-600',
                  }

                  return (
                    <div
                      key={`${row.label}-${priority}`}
                      className={`border-t border-gray-200 p-2 ${priorityColorMap[priority]}`}
                    >
                      {items.length === 0 ? (
                        <span className='text-gray-400'>-</span>
                      ) : (
                        <ul className='space-y-1'>
                          {items.map((itemValue) => (
                            <li key={itemValue} className='flex gap-2'>
                              <span>
                                {isChecked(row.fieldKey, priority, itemValue)
                                  ? '[✓]'
                                  : '[ ]'}
                              </span>
                              <span>{itemValue}</span>
                            </li>
                          ))}
                        </ul>
                      )}
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
        </div>
      </Section>
    </div>
  )
}
